window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q06"]=window.__LIBQ["the-gioi-hoan-my"]["q06"]||{};window.__LIBQ["the-gioi-hoan-my"]["q06"]["cotTruyen"]=[{"chuong":501,"tieuDe":"Bất Lão Thiên Tôn","tomTat":"Khi một bá chủ thượng giới tìm cách giáng lâm, sinh linh bất diệt liều lĩnh hút tinh khí từ vực ngoại, thi triển bí pháp phá hủy tế đàn đã giam giữ mình suốt vô tận năm tháng. Hình chiếu Bất Lão Thiên Tôn hiện ra, tụng Bất Lão tiên kinh và phối hợp với Ngũ Hành Sơn trấn áp đối thủ, nhưng sinh linh bất diệt dù nguyên khí suy kiệt vẫn phá tan phù văn thần sơn và ngoan cường phản kích. Giữa lúc đại chiến rung chuyển Bất Lão Sơn, Thạch Hạo thúc giục cha mẹ cùng Tần Hạo rời đi, song Tần Hạo từ chối vì con đường tu hành của cậu đã gắn chặt với tế đàn mang khí tức Chí Tôn. Theo lời cầu khẩn của Thạch Hạo, Tiểu Tháp cưỡng chế thu cả tế đàn, Tần Hạo và vợ chồng Thạch Tử Lăng vào trong tháp, trong khi Bất Lão Thiên Tôn bị cuộc chiến kiềm chế nên không thể ngăn cản. Nhận ra đối phương chỉ là hình chiếu có thời gian phát uy hữu hạn, Tiểu Tháp đưa Thạch Hạo rời chiến trường rồi phá cấm chế, đột nhập một động phủ chứa đầy thần liệu và thiên tài địa bảo của Bất Lão Sơn. Giữa kho báu rực rỡ, Thạch Hạo bất ngờ phát hiện một khối tàn cốt nhỏ bé, trắng bóng và trơn nhẵn; cảm nhận được sự khác thường của nó, hắn lập tức nhặt vào tay."},{"chuong":502,"tieuDe":"Tất Cả Đều Xuất Hiện","tomTat":"Trong bảo khố Bất Lão Sơn, Thạch Hạo ghép khối cốt trắng bóng với mảnh mình từng đoạt được ở Thạch quốc, xác nhận chúng có liên quan đến Nguyên Thủy Chân Giải nhưng vẫn còn thiếu mảnh cuối. Cậu cùng Tiểu Tháp và Đả Thần Thạch vét sạch kho tàng tích lũy từ thượng cổ, sau đó phá trận pháp ẩn giấu để mang đi cây Ngũ Nguyên gần chết cùng chậu đất Ngũ Hành. Bên ngoài, Bất Lão Thiên Tôn dùng Ngũ Hành Sơn giao chiến với sinh linh bất diệt, trong khi Trượng Lục kim thân của Tây Phương Giáo và một bóng mờ đeo kiếm cưỡi trâu già lần lượt giáng lâm. Sinh linh bất diệt kéo Tiểu Tháp vào vòng vây để nhờ cản địch, khiến Tiểu Tháp phải giao thủ với Trượng Lục kim thân rồi tìm cách thoát khỏi cuộc truy kích. Đúng lúc các cường giả hội tụ, một bảo giới thái cổ mở ra, thu hút sinh linh bất diệt, Tiểu Tháp và các bá chủ thượng giới đồng loạt lao vào tranh đoạt cơ duyên. Được Tiểu Tháp mang theo, Thạch Hạo gặp lại Lam Vũ, Thủy Nguyệt và Hồng Hoàng, đồng thời cảm nhận được khí tức quen thuộc của Liễu Thần trong bảo giới."},{"chuong":503,"tieuDe":"Bảo Giới Thái Cổ","tomTat":"Giữa Bảo giới thái cổ, Tiểu Tháp quyết chiến với Trượng lục kim thân, còn Sinh linh bất diệt vì nguyên khí chưa hồi phục nên liên tiếp thổ huyết dưới sự vây công của Ngũ hành sơn, Bất lão Thiên tôn và cường giả cưỡi trâu mang tiên kiếm. Trong lúc giao tranh, các cường giả vẫn dò xét cấm chế ở nơi sâu nhất và nhận ra Liễu Thần đã âm thầm tiến vào khu vực ẩn chứa cơ duyên lớn trước họ. Tiểu Tháp tách bốn tầng thân tháp thành ánh sáng hỗn độn, tái hợp thành lồng giam tạm phong ấn Trượng lục kim thân, nhưng sau đó chủ động thả đối phương vì không muốn liều mạng đến cùng. Tây Phương giáo chủ thi triển pháp tướng kim thân ngàn tay nhằm thu phục Tiểu Tháp, đồng thời hé lộ ân oán bắt nguồn từ việc Tiểu Tháp từng cướp xá lợi của Tây Phương giáo để chữa thương sau đại chiến với thượng giới. Do chân thân không trọn vẹn, Tiểu Tháp phải truyền thần năng vào Thạch Hạo, dẫn động Chí tôn cốt hóa thành xích thần trật tự và thần quang vô thượng để chống lại vòng vây. Theo lời cầu khẩn của Thạch Hạo, Tiểu Tháp còn triển khai kỳ trận, đưa khu vực có cha mẹ cậu rời khỏi Bảo giới nhằm tránh dư ba đại chiến. Khi Tiểu Tháp và Sinh linh bất diệt bị các cường giả khóa chặt giữa vòng vây, Liễu Thần bất ngờ ra tay, dùng những cành liễu hóa thành xích thần trật tự phá nổ pháp bảo của Bất lão Thiên tôn, quấn lấy Trượng lục kim thân và đánh thẳng vào mi tâm cường giả mang tiên kiếm."},{"chuong":504,"tieuDe":"Liễu Thần Vô Song","tomTat":"Trong Bảo giới thái cổ, Liễu Thần dùng những cành liễu đồng thời áp chế Tây Phương giáo chủ, cường giả cưỡi trâu, Bất lão Thiên tôn và pháp khí hỗn độn Ngũ hành sơn, đồng thời phá hủy trận đồ duy trì hình chiếu của Bất lão Thiên tôn. Vì không muốn bỏ lỡ dấu ấn trước khai thiên cùng những bảo vật cổ xưa trong bảo giới, các bá chủ thượng giới quyết định tiếp tục giao chiến. Liễu Thần hiện thân với cây liễu xanh tốt phía sau và thần bàn ba ngàn thế giới vây quanh, tạo nên dị tượng vô số thần linh tụng niệm, quỳ lạy. Khi đại hỗn chiến bùng nổ, Liễu Thần hút cạn tiên khí rồi phá hủy đoạn trúc của Tây Phương giáo chủ, sau đó dùng một ngón tay đánh văng tiên kiếm và khiến Thanh ngưu của cường giả cưỡi trâu bị dư chấn tiêu diệt. Liễu Thần tiếp tục áp sát Bất lão Thiên tôn, vận dụng pháp ấn cùng bảo thuật vô thượng điểm trúng mi tâm, đánh nổ hình chiếu của hắn và buộc hắn trở lại thượng giới. Trước sự vui mừng của Tiểu Tháp và niềm kích động của Thạch Hạo, Liễu Thần quay sang Trượng lục kim thân, người cầm tiên kiếm cùng Ngũ hành sơn, uy nghiêm yêu cầu họ rời khỏi nơi này."},{"chuong":505,"tieuDe":"Mời Lên Đường","tomTat":"Sau khi hình chiếu của Bất lão Thiên tôn bị đánh tan, các bá chủ tiếp tục hỗn chiến, trong đó Liễu Thần và Tiểu Tháp liên tục đổi mục tiêu để đối phó với Tây Phương giáo chủ, cường giả cầm tiên kiếm và Ngũ hành sơn. Liễu Thần dùng ký hiệu phản ngũ hành hấp thu tinh khí, tạm khống chế Ngũ hành sơn như một bảo ấn rồi nện nó vào tiên kiếm của đối thủ. Ngũ hành sơn sau đó để lộ việc cố ý bị bắt nhằm phối hợp với Thế giới trong lòng bàn tay của Tây Phương giáo chủ, tạo thành thế phong ấn Liễu Thần. Tuy nhiên, Liễu Thần diễn hóa đạo Sinh trưởng, khiến vô số thực vật hút cạn lực ngũ hành và pháp lực kim thân, qua đó phá tan thế hợp kích. Trước đòn tấn công từ vô số dấu ấn thiên địa cầm kiếm, Liễu Thần dung hợp đạo Côn Bằng vào các cành liễu, phá vạn pháp và chấn nát tiên kiếm. Khi đã hoàn toàn chiếm ưu thế, Liễu Thần yêu cầu các bá chủ tự trở về thượng giới hoặc để mình tiễn đi. Tây Phương giáo chủ thất bại trong lần kết ấn cuối cùng rồi rời khỏi hạ giới, cường giả tử khí cũng nối gót, còn Ngũ hành sơn vội phá hư không trốn vào hỗn độn."},{"chuong":506,"tieuDe":"Bí Ẩn","tomTat":"Tiểu Tháp và Sinh linh bất diệt truy kích nhưng không thể ngăn Ngũ Hành sơn hóa thành khí bản nguyên, mượn điện đồng của Bất Lão sơn để thoát khỏi tám vực và tiến lên thượng giới. Trở lại Bảo giới thái cổ, Thạch Hạo dùng con mắt Trùng đồng dò xét Sinh linh bất diệt nhưng chỉ thấy thần quang vàng rực, rồi được biết đối phương vốn là sinh linh hậu thiên đã được thai nghén hơn trăm vạn năm trong một tiểu thế giới hỗn độn để mang dấu ấn tiên thiên. Liễu Thần, Tiểu Tháp và Sinh linh bất diệt cùng luận về hình thể thích hợp với đại đạo, đồng thời chỉ ra rằng sở trường mạnh nhất đôi khi cũng trở thành cửa ải cản trở đột phá; cuộc trò chuyện còn hé lộ Liễu Thần có thể từng trải qua một trận quyết chiến sinh tử bí ẩn. Khi bàn tới khối cốt mới trong ngực Thạch Hạo, ba bá chủ đưa ra những quan điểm khác nhau về việc giữ lại hay chặt bỏ, nhưng cuối cùng để cậu tự lựa chọn con đường tu hành. Liễu Thần cảm ứng cánh cửa nguyên thủy sắp tái hiện trong vùng hỗn độn, nơi từng khiến mọi người bước vào đều biến mất, song vẫn quyết định tiến đến kiểm tra cùng Tiểu Tháp và Sinh linh bất diệt. Vì tu vi chưa đủ, Thạch Hạo bị truyền tống ra ngoài, chỉ nhận được lời hứa rằng Liễu Thần sẽ xử lý mối họa từ thượng giới trước khi rời đi, trong khi cha mẹ cậu vẫn chưa được giải khỏi trận pháp. Nhận ra những chỗ dựa lớn có thể sắp biến mất, Thạch Hạo chuẩn bị tự lực tranh đoạt cơ duyên giữa lúc các kỳ tài thượng giới và một con Kim ô bản địa đáng sợ cùng hội tụ về vùng nguyên thủy."},{"chuong":507,"tieuDe":"Biển Kim Ô Tái Hiện","tomTat":"Trong lúc thăm dò Bảo giới thái cổ, Thạch Hạo tránh đối đầu với một Kim Ô cấp Tôn giả và đại quân Hỏa nha đang truy lùng những kẻ xâm phạm tổ địa. Nó lần theo tung tích của chúng, phát hiện thành trì Hỏa nha cùng tám hồ Địa hỏa dịch, nhưng quyết định không mạo hiểm trước lực lượng hùng hậu của cả bộ tộc. Hai ngày sau, Thạch Hạo tìm được một động phủ bỏ hoang và hấp thu trọn ao thạch nhũ vạn năm, giúp Chí tôn cốt tiếp tục trưởng thành, đồng thời làm những phù văn của bảo thuật bản mệnh dần hiện rõ. Đúng lúc ấy, trận pháp cổ phía sau thành Kim Ô tan rã, để lộ tổ địa bị phong ấn cùng biển dung nham có quy tắc cấm không đủ sức uy hiếp cả Tôn giả. Thạch Hạo thi triển pháp môn Côn Bằng chạy tới, bắt gặp nhiều Tôn giả bản địa và nhóm kỳ tài thượng giới do Tuyên Minh dẫn đầu đang chuẩn bị tranh đoạt cơ duyên. Khi thần lực trong biển hóa thành Thần thụ Thái dương, nhật nguyệt tinh thần và một tòa cung điện bất hủ, mọi người nhận ra di tích từ thời đại thần thoại khởi nguyên đã tái hiện. Thạch Hạo chấn động nhận định cơ duyên ẩn trong biển Kim Ô có thể còn lớn hơn cả vùng hỗn độn mà Tiểu tháp và Liễu Thần từng tiến vào."},{"chuong":508,"tieuDe":"Thần Thụ Thái Dương","tomTat":"Giữa Bảo giới thái cổ, thần thụ Thái Dương tái hiện trong biển dung nham có sức nóng đủ nung chảy pháp khí thông thường, thu hút đông đảo Tôn giả và kỳ tài thượng giới. Hai đạo nhân Kim ô tuyên bố nơi này là tổ địa, nhưng trước sự phản đối của Rắn chín đầu, Người khổng lồ hoàng kim, Cổ thụ Thiết huyết và Kiến tử kim, họ buộc phải để các bên dựa vào cơ duyên và bản lĩnh tranh đoạt. Thạch Hạo nhận lời đồng hành cùng nhóm Hồng Hoàng, Lam Vũ và Tuyên Minh trên ba bảo thuyền thần linh, đồng thời che giấu biến cố thật sự tại Bất Lão sơn trước những ánh mắt nghi ngờ. Sau khi bị thuyền xương Kim ô cảnh cáo, đoàn người lại rơi vào vòng vây của cổ thuyền ma, Quỷ thần binh và vô số bạch cốt từ chiến trường thái cổ, buộc Tuyên Minh dùng cầu đá xuyên qua khu vực cấm không để thoát thân. Họ tránh các cổ thuyền và vượt biển suốt năm ngày mới đến được nơi thần thụ cắm rễ, rồi kinh ngạc phát hiện cây hoàng kim thực chất chỉ cao khoảng một thước, mỗi chiếc lá nâng một ngôi sao và trên tán có cổ điện phun nuốt khí hỗn độn. Khi một vị Tôn giả tiến tới chụp lấy thần thụ, thân thể ông ta liên tục thu nhỏ cho đến khi chỉ còn như hạt bụi, hé lộ quy tắc không gian giới tử nạp Tu Di kỳ dị quanh cây. Dù vậy, mấy vị Tôn giả vẫn nhận ra đây chính là mục tiêu họ tìm kiếm và vui mừng lao tới tranh đoạt."},{"chuong":509,"tieuDe":"Quyết Liệt","tomTat":"Trước cây Hoàng kim, cổ thụ Thiết huyết cùng hàng loạt Tôn giả Bảo giới bất ngờ hợp sức vây giết đoàn thiên tài thượng giới, khiến một số người nhanh chóng mất mạng. Đối mặt với thế công dữ dội của Lam Long, Rắn chín đầu và Kiến tử kim, Tuyên Minh triển khai cầu đá nối liền hư không, đưa mọi người phá vòng vây tiến đến thần thụ. Trên đường chạy trốn, Triệu Khải và Trác Vân ngấm ngầm muốn đẩy Thạch Hạo xuống cuối đoàn cản truy binh, nhưng cậu vẫn bám sát và cùng họ tới trước cấm chế hoàng kim. Sau khi phát hiện chỉ sức mạnh tiểu thế giới mới có thể mở màn sáng, Oánh Oánh lấy ra một tiểu thế giới hư hao, còn Thạch Hạo dùng Thế giới hộp quý để hợp lực khai thông lối vào. Vừa vượt qua cấm chế, có người trong đoàn lập tức cướp hộp quý và âm thầm tập kích Thạch Hạo, song cậu thuận thế giả vờ trúng đòn, chủ động rơi xuống biển địa hỏa dịch dưới rễ cây. Không những không bị tổn thương, Thạch Hạo còn khiến Chí tôn cốt thức tỉnh và điên cuồng hấp thu tinh hoa, rồi phấn khích lặn sâu xuống nơi ẩn chứa linh dịch có thần năng mạnh mẽ hơn."},{"chuong":510,"tieuDe":"Niết Bàn Tái Sinh","tomTat":"Sau khi lặn hàng chục dặm mà vẫn không thể thăm dò hết hệ rễ Hoàng kim thụ, Thạch Hạo quay lại biển địa hỏa dịch để chuyên tâm phục hồi Chí tôn cốt. Nó hấp thu lượng lớn tinh hoa thần tính suốt ba ngày ba đêm, trong khi Đả Thần Thạch điên cuồng nuốt linh dịch còn Hoàng điệp bám lên màn sáng của thần thụ Thái dương để thu lấy thần nguyên. Nhận ra địa hỏa dịch thông thường chưa đủ giúp bảo cốt viên mãn, Thạch Hạo thi triển pháp môn Côn Bằng lặn sâu, tìm được tinh hoa gần đạt thần dịch do rễ hoàng kim luyện hóa. Sau đó, nó dùng Thế giới hộp quý xuyên qua màn sáng, lên một cành thần thụ hấp thu thêm bản nguyên từ thân cây, lá cây và những ngôi sao đang thai nghén, khiến Chí tôn cốt hoàn toàn tái sinh cùng một hệ phù văn phức tạp hơn trước. Dị tượng tụng kinh và gợn sóng đại đạo truyền lên phía trên khiến các Tôn giả cùng kỳ tài thượng giới lầm tưởng tiên kinh sắp xuất thế trong cung điện cổ Hỗn độn. Thạch Hạo lựa chọn phù văn Chí tôn cốt làm trận pháp bản mệnh, khắc chúng vào máu thịt và phủ tạng, nhờ đó đột phá tới Liệt trận cảnh hậu kỳ chỉ sau một ngày một đêm. Dù vẫn còn nhiều vật chất thần tính, nó chủ động dừng tu luyện để củng cố căn cơ và kịp trở lại tham gia cuộc tranh đoạt cơ duyên đang gần kết thúc."},{"chuong":511,"tieuDe":"Dùng Dao Mổ Trâu Cắt Tiết Gà","tomTat":"Sau khi hoàn tất niết bàn, Thạch Hạo hội ngộ Đả Thần Thạch và Hoàng điệp, nhận ra cả hai đều thu được lợi ích lớn từ tinh hoa dung nham và ánh sáng bản nguyên của Thái dương thụ. Nó đưa Nguyệt Thiền ra khỏi Hộp báu đồng thau, dùng không gian bên trong thu gom địa hỏa dịch để dành cho tộc nhân và Thạch quốc, rồi cùng đồng bạn trèo lên Hoàng kim thụ. Trên đường đi, họ phát hiện cổ thụ đã vượt khỏi phạm trù Thái dương thụ, mỗi chiếc lá đều nâng đỡ một ngôi sao đang thai nghén và toàn thân cây có xu hướng tiến hóa thành Thế giới thụ. Tại chiến trường cổ đại trên cây, một con Hươu năm màu cấp Tôn giả bất ngờ đánh lén và ép Thạch Hạo giao pháp bảo, nhưng thần hoàn do phù văn tự thai nghén của nó đã hóa giải bảo thuật, phá nát binh khí rồi thiêu hủy đối thủ. Chiến thắng vượt qua một đại cảnh giới khiến sức mạnh của Thạch Hạo được Hươu năm màu nhận ra là Chí tôn sơ cấp, còn bản thân nó cũng nhờ trận chiến mà hiểu sâu hơn về pháp môn mới. Tiếp tục tiến lên qua sương mù hoàng kim và những di tích liên quan đến Kim ô, Thạch Hạo nhìn thấy Cổ điện Hỗn độn gần đỉnh cây, đồng thời phát hiện một nhóm người đang giao chiến trên Núi thế giới do Thế giới thụ thai nghén."},{"chuong":512,"tieuDe":"Núi Thế Giới","tomTat":"Thạch Hạo và Đả Thần Thạch tiếp cận Núi Thế Giới, một phôi thô chí bảo Hỗn độn mang pháp tắc bản nguyên, cứng đến mức thần khí cũng không thể làm tổn hại. Tiến lên đỉnh núi, Thạch Hạo gặp nhóm kỳ tài thượng giới cùng các Tôn giả đang tranh giành thần hoa Thái Dương, đóa hoa có thể kết thành Quả Thế Giới và được bảo vệ bởi xích thần trật tự vô cùng đáng sợ. Khi thần hoa tiết ra ba giọt bảo dịch hoàng kim, các bên lập tức lao vào một trận hỗn chiến dữ dội. Một kẻ từng ám hại Thạch Hạo định đẩy cậu về phía Rắn chín đầu làm bia đỡ đạn, nhưng bị cậu bắt lại rồi ném thẳng vào vòng vây của các Tôn giả. Trước sự công kích của nhóm Trác Vân, Thạch Hạo vận dụng phù văn thần bí xóa diệt một đối thủ và khiến Trác Vân mất một cánh tay, làm những người còn lại kinh hãi dè chừng. Cuối cùng, nhờ màn sáng phù văn hộ thể, Thạch Hạo xông xuyên chiến trường, va Người khổng lồ hoàng kim lảo đảo rồi cướp lấy ngọc đỉnh chứa trọn ba giọt bảo dịch."},{"chuong":513,"tieuDe":"Luân Hồi","tomTat":"Thạch Hạo đoạt được ngọc đỉnh chứa ba giọt thần dịch Thái dương, sau đó khoác Bất diệt kim thân và đánh lui Người khổng lồ hoàng kim đang muốn cướp lại bảo vật. Trước sự vây công của Quỷ đằng, Ngân sư, Kim ô cùng nhiều thiên tài thượng giới, hắn thi triển bảo thuật Toan Nghê, dùng lôi điện và sương mù phong bế cảm giác khiến chiến trường rơi vào hỗn loạn. Khi Quỷ đằng dò ra vị trí của hắn, Thạch Hạo lần đầu chủ động vận dụng sức mạnh Chí tôn cốt, thi triển Luân Hồi khiến đối phương mất sạch sinh cơ, khô héo rồi hóa thành tro. Ác ma viên tiếp tục lao vào cận chiến nhưng bị lực Côn bằng đánh nát hai tay, sau đó bị Thạch Hạo dùng tay không xé đôi. Việc hai Tôn giả liên tiếp bỏ mạng khiến những cường giả còn lại kinh hãi, không dám tiếp tục vây công hắn. Đúng lúc thế giằng co hình thành, hoa Thái dương trên đỉnh núi Thế giới nở rộ, để lộ một quả trứng trong suốt đang hấp thu tinh hoa thần dược, bên trong là một cô gái tóc vàng xinh đẹp còn say ngủ."},{"chuong":514,"tieuDe":"Cổ Điện Hỗn Độn","tomTat":"Trong thần hoa Thái dương, quả trứng vàng hấp thụ toàn bộ thần dịch và để lộ một cô gái tóc vàng tuyệt mỹ, khiến mọi người suy đoán nàng là thần thai thiên địa, tinh linh thần thụ hoặc Ô hoàng tái sinh. Hỏa tinh Thái dương quanh quả trứng đánh trọng thương Rắn chín đầu và thiêu chết một Tôn giả, buộc đám đông phải dè chừng. Khi hoa hoàng kim mang quả trứng bay vào cung điện Hỗn Độn, các tu sĩ men theo cành vàng vượt qua cấm chế, rồi nhanh chóng chia thành hai phe đối địch; nhóm thiên tài thượng giới phải lôi kéo Thạch Hạo và dùng cầu đá của Tuyên Minh để thoát khỏi vòng vây của các Tôn giả. Tại nơi sâu nhất trong cổ điện, họ thấy cô gái trong trứng ngồi giữa phù văn trên đạo đài cùng hai quyển cốt thư tỏa khí hỗn độn mà không ai có thể tiếp cận. Triệu Khải và Trác Vân đòi Thạch Hạo chia thần dịch hoàng kim, sau đó còn muốn ép hắn mặc chiến y Bất diệt kim thân thăm dò cốt thư, khiến mâu thuẫn từ vụ đánh lén trước đó bùng phát thành giao chiến. Thạch Hạo vận dụng Chí tôn cốt qua pháp kiếm vàng, thi triển sức mạnh Luân hồi khiến Trác Vân và ba đồng bọn trở lại hình dạng trẻ nhỏ, thực lực suy giảm nghiêm trọng. Nhân lúc đối thủ suy yếu, hắn lạnh lùng vung kiếm chém đầu Trác Vân, kết thúc trận chiến trong chớp mắt."},{"chuong":515,"tieuDe":"Đối Đầu","tomTat":"Thạch Hạo dùng pháp kiếm màu vàng diệt sạch thần hồn Trác Vân, rồi tạm ngừng truy sát ba kẻ còn lại để quan sát và xác nhận hiệu lực biến nhỏ của sức mạnh Luân hồi chỉ duy trì trong thời gian hữu hạn. Khi phát hiện một thiên tài thượng giới bí mật đề nghị hợp lực giết mình để cướp hoàng kim dịch, nó vượt qua sự ngăn cản của đám đông, vận dụng Luân hồi cướp đi năm tháng của đối phương rồi đánh thân thể già yếu thành tro. Hành động quyết liệt ấy khiến nhóm thiên tài thượng giới rạn nứt sâu sắc, đặc biệt là phe Triệu Khải công khai cô lập Thạch Hạo và chuẩn bị liên thủ đối phó nó. Thạch Hạo tiến về bàn đá và giá sách để đoạt hai bộ cốt thư tỏa khí hỗn độn, trong khi những người khác âm thầm chờ cơ hội cướp lại. Người khổng lồ hoàng kim, Rắn chín đầu, Ngân sư, đạo nhân Kim ô và Cổ thụ Thiết huyết lần lượt kéo đến, nhận định hai bộ điển tịch là tiên kinh vô thượng và lợi dụng sự chia rẽ của nhóm ngoại lai để ra tay. Trước sự vây công của các Tôn giả cùng phe Triệu Khải, Thạch Hạo dung hợp Bất diệt kim thân, dùng pháp kiếm chống lại Sư tử hống và trực tiếp đấu quyền với Người khổng lồ hoàng kim. Giữa lúc Tuyên Minh, Bích Cổ và Thủy Nguyệt lao tới tranh đoạt cốt thư, hỗn chiến bao trùm cổ điện, còn Thạch Hạo lạnh lùng tuyên bố sẽ đại khai sát giới."},{"chuong":516,"tieuDe":"Đoạt Sách Quý Hỗn Độn","tomTat":"Trong Cổ điện Hỗn Độn, Thạch Hạo bị nhóm kỳ tài thượng giới và các sinh linh Bảo giới thái cổ hợp sức vây giết nhằm cướp Bất diệt kim thân. Hắn lấy thân làm mồi, dùng lôi điện Toan Nghê cùng mười Động thiên khóa chặt hư không rồi chém đầu sát thủ tóc tím; sau đó lợi dụng đoản mâu Hư không thú tự hủy để đánh nát Kim lang. Trước thế công dồn dập, Thạch Hạo thi triển Luân hồi khiến hàng loạt đối thủ suy lão, giẫm chết hai kẻ bên cạnh Triệu Khải, diệt Ngân sư bằng sóng âm và chém lìa một tay Người khổng lồ hoàng kim. Tuy nhiên, hắn cũng nhận ra Luân hồi không thể sử dụng liên tiếp, tiêu hao thân thể cực lớn và giảm hiệu lực khi tác động lên quá nhiều mục tiêu. Giữa lúc hỗn chiến, huyết dịch kích hoạt trận pháp quanh bàn đá, giúp Bích Cổ đoạt được sách quý Hỗn Độn rồi chuyển nó cho Triệu Khải để tránh sát cơ tập trung. Biết mình không thể thoát khỏi vòng vây, Triệu Khải ném cốt thư về phía Thạch Hạo với ý định biến hắn thành mục tiêu chung, nhưng Thạch Hạo đã đoán trước, dùng thân pháp Côn bằng đoạt lấy bảo vật và xé Triệu Khải làm đôi. Sách quý Hỗn Độn cuối cùng rơi vào tay Thạch Hạo, khiến toàn bộ cường giả trong cổ điện chấn động và sát ý của các phe tiếp tục dồn về phía hắn."},{"chuong":517,"tieuDe":"Chân Giải","tomTat":"Sau khi Triệu Khải tử vong, Thạch Hạo đoạt được cốt thư nhưng lập tức trở thành mục tiêu vây công của các Tôn giả trong cổ điện. Bất chấp tinh hỏa Thái dương và hàng loạt sát chiêu, nó dùng thần thức quan sát phù văn, xác nhận khối cốt khắc Nguyên thủy chân giải. Khi lục lạc của Lam long ép nguyên thần rời khỏi thân thể, Thạch Hạo bình tĩnh vượt qua thế công nhằm vào cả thể xác lẫn thần hồn, rồi ném cốt thư cho Rắn chín đầu để chuyển hướng cuộc truy sát. Rắn chín đầu nhanh chóng bị Thủy Nguyệt, Người khổng lồ hoàng kim và các cường giả khác vây đánh, khiến cốt thư thứ nhất tiếp tục đổi chủ giữa cuộc hỗn chiến. Cùng lúc, tinh huyết chảy vào các rãnh dưới giá sách làm trận pháp phục sinh, đưa cốt thư thứ hai xuất hiện và châm ngòi cho cuộc tranh đoạt giữa Tuyên Minh, Kiến tử kim, Hồng Hoàng cùng nhiều người khác. Lam long giành được cốt thư, nhưng Thạch Hạo vận dụng lực Luân hồi khiến lục lạc nứt vỡ và đối phương thoái hóa thành con non, sau đó đánh bật nó, đoạt lấy cốt thư rồi rời đi. Mang theo chiến lợi phẩm mới, Thạch Hạo thầm nghi ngờ đây chính là thiên thứ hai mang tên Siêu thoát của Nguyên thủy chân giải."},{"chuong":518,"tieuDe":"Thiên Đế Chưa Từng Đạt Được Tạo Hóa","tomTat":"Giữa cuộc hỗn chiến tranh đoạt cốt thư, Lam long thiêu đốt tinh khí, dùng U hỏa địa ngục đánh lén Thạch Hạo nhưng vẫn bị pháp môn Côn bằng áp chế và giết chết, còn thi thể bị thu vào túi càn khôn nơi Nguyệt Thiền đang bị giam giữ. Bích Cổ thoáng thấy bóng dáng một cô gái trong túi nên nghi đó là Nguyệt Thiền, song Thạch Hạo không trả lời trực tiếp. Một đạo nhân Kim ô kích hoạt cấm chế khiến tinh hỏa Thái dương tràn ngập cổ điện, trong khi một bộ cốt thư tự bay vào hoàng kim hoa, nơi các pháp khí bị phân giải thành tinh khí để nuôi dưỡng quả trứng vàng và kẻ công kích bị xích thần trật tự giết chết. Khi bộ cốt thư còn lại cũng bị bí lực triệu hồi, Lam Vũ, Thủy Nguyệt, Hồng Hoàng, Tuyên Minh, Bích Cổ cùng các Tôn giả tạm thời hợp sức giúp Thạch Hạo giữ nó và tìm đường rời khỏi cổ điện. Trong lúc tháo chạy, Thạch Hạo phá được lớp sáng trên cốt thư, ghi nhớ toàn bộ những ký hiệu tiết lộ manh mối về một tạo hóa lớn đến mức ngay cả vị Thiên đế để lại lời nhắn cũng chưa từng đạt được. Khi bóng người mang khí tức vô thượng hiện lên trên bồ đoàn, Thạch Hạo kịp thời buông tay, còn Rắn chín đầu cố đoạt cốt thư liền bị nghiền nát đuôi trước khi cổ kinh trở về đạo đài. Cuối cùng, cổ thụ Thái dương tỏa thần quang, nâng cả núi Thế giới lẫn cổ điện Hỗn độn phá trời bay lên, khiến Hồng Hoàng hoảng hốt nhận ra khí tức của thượng giới."},{"chuong":519,"tieuDe":"Rời Đi","tomTat":"Cổ thụ Thái dương nhổ rễ khỏi biển dung nham, mang theo núi Thế giới, cổ điện Hỗn độn và hai khối cốt thư biến mất qua khe nứt hư không, có khả năng đã tiến vào thượng giới. Khi địa hỏa dịch bị hút gần cạn và khu vực khôi phục khả năng phi hành, các Tôn giả lập tức vây ép Thạch Hạo giao ra phần tiên kinh mà họ nghi hắn đã ghi nhớ. Chiến đảo, núi Rắn, tổ kiến thiên thạch cùng trận pháp của bộ tộc Cổ thụ Thiết huyết đồng loạt phát động sát trận, còn Tuyên Minh dùng cầu đá đưa nhóm thiên tài thượng giới rời khỏi vòng vây. Nhờ Đả Thần Thạch nhận diện thế Tứ tượng và Ngũ hành, Thạch Hạo xuyên qua sát quang, áp sát rồi lần lượt giết Người khổng lồ hoàng kim, Kiến tử kim và Rắn chín đầu. Hắn tiếp tục vận dụng kiếm khí thông thiên của một cây cỏ chém nát Cổ thụ Thiết huyết, phá tan vòng vây và khiến lực lượng các tộc kinh hãi rút lui. Rời chiến trường, Thạch Hạo tìm đến một tòa trận pháp tràn ngập khí hỗn độn và phát hiện cha mẹ cùng đệ đệ vẫn đang bị niêm phong bên trong."},{"chuong":520,"tieuDe":"Ma Đế","tomTat":"Tiểu Tháp trở về sau chuyến cùng Liễu Thần truy tìm cánh cửa nguyên thủy trong biển hỗn độn, rồi đau xót khi biết mình đã bỏ lỡ hàng loạt thần liệu và cơ duyên quý giá. Sau khi nó thu hồi trận pháp hỗn độn, Thạch Hạo cuối cùng cũng đoàn tụ với cha mẹ, nhưng Tần Hạo vẫn miễn cưỡng nhận anh và kiên quyết từ chối Hoàng kim dịch vì oán hắn đã giết Tần Pháp, xới tung Bất Lão sơn. Không thể lập tức hóa giải khúc mắc với em trai, Thạch Hạo giao thần dịch cho cha mẹ giữ, song họ chỉ nhận một giọt. Khi đoàn người rời Bảo giới thái cổ, các tu sĩ Huyền vực nhận ra Thạch Hạo chính là Nhân hoàng trẻ tuổi từng một mình náo loạn Bất Lão sơn và kính sợ gọi hắn là Ma đế. Nhóm thiên tài thượng giới vì thế phải đánh giá lại thực lực của hắn, đồng thời thầm mừng vì trước đó chưa trực tiếp đối địch. Nửa tháng sau, Thạch Hạo đưa gia đình trở về hoàng cung Thạch đô và gặp Ma nữ đã chờ sẵn; nàng báo rằng Nguyệt Thiền sắp gặp một tai vạ khó tránh."},{"chuong":521,"tieuDe":"Thứ Thân","tomTat":"Ma nữ tìm gặp Thạch Hạo và tiết lộ Nguyệt Thiền bị hắn bắt thực chất là thứ thân bằng máu thịt, trong khi chủ thân vẫn nguyên vẹn và đang ẩn mình tu luyện. Nàng giải thích Nguyệt Thiền đã tu thành cổ pháp Thần thai tái sinh, nhờ đó chủ thân và thứ thân có thể cùng tu hành, hỗ trợ phục sinh và cuối cùng hợp nhất để đạt tới viên mãn. Tuy nhiên, chỉ cần thứ thân còn sống trong tay Thạch Hạo, chủ thân sẽ không thể lột xác tạo ra một thân mới. Ma nữ còn cảnh báo Nguyệt Thiền có thể đang cố ý ẩn nhẫn để dò xét pháp môn Côn Bằng, Nguyên thủy chân giải và bảo thuật trong Chí tôn cốt, đồng thời chờ cơ hội vận dụng sức mạnh ẩn sau cửa hoàng kim để phản kích. Nhận ra mối họa, Thạch Hạo quyết định không chỉ khống chế thứ thân mà còn tìm kiếm và trấn áp cả chủ thân. Cuối cùng, Ma nữ lấy ra Trấn thần châu, định dùng pháp bảo này ngăn thứ thân phản kháng hoặc tự hủy, biến nàng thành điểm kiềm chế lâu dài đối với chủ thân."},{"chuong":522,"tieuDe":"Trấn Thần","tomTat":"Ma nữ mang Trấn thần châu đến, đề nghị Thạch Hạo dựng trận phong tỏa thần thức rồi cùng nàng xâm nhập thức hải Nguyệt Thiền để tìm cổ pháp Thần thai niết bàn của Bổ Thiên giáo. Trước khi bế quan, Thạch Hạo báo cho cha mẹ; trong lúc ấy, Thạch Tử Lăng và thê tử trở lại Thạch đô, khiến cả hoàng đô náo động vì chiến tích của con trai tại Bất Lão sơn. Dù Nguyệt Thiền nhiều lần cảnh báo rằng Ma nữ chưa từng để lộ chân thân và có thể đang giăng bẫy, Thạch Hạo vẫn tin vào ưu thế của mình trong hoàng cung và quyết định tiếp tục kế hoạch. Thần thức của hắn và Ma nữ tiến vào thức hải Nguyệt Thiền, dùng Trấn thần châu cố định không gian và Nhân hoàng ấn hộ thân, sau đó mở ngọc cung đánh thức một Nguyệt Thiền khác có thần hồn mạnh vượt cảnh giới. Đại chiến bùng phát khi Nguyệt Thiền dùng chân long và tiên hoàng chống lại kiếm khí cùng những cánh hoa khắc dấu Đạo của hai kẻ xâm nhập. Trước sức kháng cự dữ dội của nàng, Ma nữ kích phát lĩnh vực trấn áp của Trấn thần châu rồi thi triển Tiệt thiên thuật, đồng thời Thạch Hạo vận dụng pháp môn Côn bằng. Dưới thế hợp kích của hai người và sức ép từ chí bảo thượng cổ, Nguyệt Thiền cuối cùng bị phù văn niêm phong hoàn toàn trong thức hải."},{"chuong":523,"tieuDe":"Bắt Giữ Tiên Tử","tomTat":"Sau cuộc giao tranh thần thức, Thạch Hạo và Ma nữ đã dùng xích thần trật tự cùng Trấn thần châu khóa chặt nguyên thần và đạo hạnh của Nguyệt Thiền. Dù rơi vào cảnh tù nhân, Nguyệt Thiền vẫn tìm cách chia rẽ hai người, cảnh báo Thạch Hạo về sự nguy hiểm của Ma nữ và đề nghị giúp nó trấn áp nàng. Thạch Hạo không hoàn toàn tin bên nào, âm thầm vận dụng Nhân Hoàng ấn, long khí và quốc vận để đề phòng Ma nữ trở mặt trong lúc nàng hoàn tất phong ấn. Trấn thần châu sau đó chém hút Tam hoa của Nguyệt Thiền, giúp Ma nữ đoạt được một phần đạo quả, nhưng áo nghĩa tối cao của Bổ Thiên giáo vẫn bị giấu kín trong ấn ký bản nguyên. Khi cả hai rời khỏi biển ý thức, Nguyệt Thiền tỉnh lại trong tình trạng nguyên thần bị phong ấn hoàn toàn và không còn thủ đoạn phản kháng tức thời. Năm tầng trận pháp thần linh bất ngờ hiện ra phong tỏa hư không, còn Thạch Hạo tiếp tục yêu cầu hai tiên tử truyền cho mình những biến hóa của Bổ Thiên thuật, chân long và tiên hoàng."},{"chuong":524,"tieuDe":"Mẹ Chồng Nàng Dâu","tomTat":"Thạch Hạo kích hoạt năm tầng trận pháp thần linh, vận dụng Nhân Hoàng ấn và long khí hoàng cung để phong tỏa sân viện, vừa ngăn Nguyệt Thiền đào thoát vừa ép Ma nữ giao ra những bảo thuật mà nàng có thể đã đoạt được. Nguyệt Thiền hứa truyền bảo thuật nếu hắn bắt Ma nữ, nhưng Ma nữ không chịu giả vờ quy hàng mà dùng Trấn Thần châu chống lại phù văn rồi xuyên thủng đại trận. Khi Thạch Hạo gọi Tiểu tháp trợ chiến, nó từ chối làm hại Ma nữ vì từng hứa với một cố nhân rằng sẽ không tổn thương hậu thế nắm giữ thạch châu, nhờ đó Ma nữ rời hoàng cung an toàn. Sau khi thu trận, Thạch Hạo đưa Nguyệt Thiền vào trung ương Thiên cung, lúng túng giới thiệu nàng với Thạch Tử Lăng, Tần Di Ninh và Tần Hạo như một tù binh. Tần Di Ninh nhận ra thánh nữ Bổ Thiên giáo mà bà từng đến thăm khi mới chào đời, nhanh chóng trở nên thân thiết với nàng và còn trách con trai không được bắt nạt nàng. Nguyệt Thiền tưởng có thể lợi dụng quan hệ giữa Bổ Thiên giáo và Bất Lão sơn để thoát vây, nhưng nụ cười lập tức cứng lại khi Tần Di Ninh bất ngờ thúc giục nàng cùng Thạch Hạo sớm thành hôn. Nhận thấy tuệ quang trong mắt mẫu thân, Thạch Hạo hiểu lời đề nghị ấy không hề đơn giản nhưng nhất thời không biết phải đáp lại thế nào."},{"chuong":525,"tieuDe":"Đại Chiến Giữa Mẹ Chồng Nàng Dâu","tomTat":"Nguyệt Thiền tìm cách dựa vào quan hệ giữa Bổ Thiên giáo và Bất Lão sơn để nhờ Tần Di Ninh giải vây, nhưng mọi lời cầu xin của nàng đều bị bà khéo léo biến thành lý do kết duyên với Thạch Hạo. Tần Di Ninh bí mật cho Thạch Tử Lăng biết bà muốn dùng thân phận đặc biệt của Nguyệt Thiền và cuộc thông gia này để hóa giải tai họa Thạch Hạo đã gây ra tại Bất Lão sơn. Khi Nguyệt Thiền cảnh báo việc cưỡng ép hôn nhân có thể châm ngòi đại chiến giữa các thế lực thượng giới, Tần Di Ninh vẫn áp đảo nàng bằng thân phận trưởng bối, đồng thời nhắc lại việc nàng từng mưu đoạt Thạch Quốc và vây công Thạch Hạo. Bất chấp sự can ngăn của Thạch Hạo, Tần Hạo và lời cảnh báo từ Bằng Cửu, bà quyết định tổ chức một hôn lễ đơn giản ngay trong đêm. Thạch Hạo sau đó tiết lộ Nguyệt Thiền trước mặt họ chỉ là thứ thân được tạo ra từ một môn cổ pháp, nhưng điều này càng khiến Tần Di Ninh muốn nhanh chóng hoàn tất hôn sự trước khi bản thể của nàng xuất hiện. Trước thái độ kiên quyết của Tần Di Ninh và việc Bằng Cửu thực sự rời đi chuẩn bị hôn lễ, Nguyệt Thiền cuối cùng không còn giữ được bình tĩnh và sợ hãi tái mặt."},{"chuong":526,"tieuDe":"Kết Hôn","tomTat":"Trong trung ương thiên cung của hoàng cung Thạch Quốc, Thạch Hạo và Nguyệt Thiền cử hành một hôn lễ bí mật trước sự chứng kiến của cha mẹ Thạch Hạo, Tần Hạo, Chiến Vương và Bằng Cửu. Tần Di Ninh liên tục nhắc đến chuyện phong quý phi, động phòng và sớm sinh cháu, khiến Nguyệt Thiền dù cố đấu khẩu vẫn dần mất bình tĩnh. Khi bị đưa vào phòng tân hôn, Nguyệt Thiền không thể thoát đi vì tu vi đã bị phong bế và nguyên thần bị trấn áp, còn Thạch Hạo cố ý gọi nàng là vợ rồi trêu chọc bằng chuyện sinh hai, ba đứa con. Để trì hoãn tình thế, nàng tuyên bố sẽ thừa nhận cuộc hôn nhân nếu Thạch Hạo bắt được Ma nữ và đưa vào hoàng cung bầu bạn với mình. Thạch Hạo không chấp nhận điều kiện ấy, nhưng tỏ ra hứng thú với việc trấn áp Ma nữ vì đối phương từng muốn ra tay với nó trong biển ý thức của Nguyệt Thiền. Cuối cùng, nó lấy cớ đôi bên còn bất đồng để hoãn cuộc thương lượng sang ngày hôm sau, khép lại đêm tân hôn bằng một nụ cười đầy dụng ý."},{"chuong":527,"tieuDe":"Ngày Tốt Cảnh Đẹp","tomTat":"Nguyệt Thiền tiếp tục thương lượng với Thạch Hạo nhưng điều kiện của nàng không được chấp nhận, còn nỗ lực bí mật phá phong ấn nguyên thần cũng hoàn toàn thất bại. Trước tình thế mất quyền chủ động, nàng đành cùng Thạch Hạo uống rượu giao bôi và chuyển sang yêu cầu nó bắt Ma nữ, song cả hai vẫn luôn đề phòng lẫn nhau. Trong phòng tân hôn, Nguyệt Thiền tụng chân kinh để phân tâm và quyết liệt chống cự, còn Thạch Hạo tìm cách ngăn nàng né tránh rồi cưỡng ép ôm hôn nàng. Khi phát hiện dao động khả nghi ngoài thành, Thạch Hạo mang theo Nguyệt Thiền đi điều tra vì lo đây là kế điệu hổ ly sơn, nhưng người âm thầm theo dõi lại là Tần Di Ninh đang canh chừng để bảo vệ con trai. Việc này khiến Nguyệt Thiền nổi giận và xung đột với Tần Di Ninh, trong khi Thạch Hạo lập tức đứng về phía mẹ mình. Sau khi trở lại phòng, Nguyệt Thiền nghiêm túc tiết lộ rằng chủ thân của nàng sắp tới và đề nghị Thạch Hạo bắt lấy người ấy, mở ra một biến số mới mà nó vẫn chưa hoàn toàn tin tưởng."},{"chuong":528,"tieuDe":"Chủ Thân","tomTat":"Trong phòng tân hôn, Nguyệt Thiền tiết lộ nàng và chủ thân tuy vốn cùng một thể nhưng đã trở thành hai thần thai máu thịt riêng biệt, đồng thời chỉ khi một bên chết thì bên còn lại mới có thể tái tạo thần thể hoàn mỹ thứ ba. Nàng lo rằng nếu chủ thân không giết được Thạch Hạo thì sẽ quay sang thanh trừ mình, song Thạch Hạo vẫn chưa hoàn toàn tin lời nàng. Đúng lúc ấy, vô số sao băng bị một sinh linh điều khiển đồng loạt giáng xuống hoàng cung Thạch quốc, tạo ra uy thế đủ khiến Tôn giả kinh sợ. Trận pháp thần linh do Đả Thần Thạch bố trí bằng thần liệu từ Bất Lão sơn lập tức thức tỉnh, khiến toàn bộ thiên thạch nổ tung trước khi xuyên thủng phòng tuyến. Nhìn xuyên qua màn mưa sao băng, Thạch Hạo phát hiện chủ thân của Nguyệt Thiền đang đứng giữa tầng mây, được thần quang bao phủ và tỏa ra khí tức thánh khiết mạnh hơn thứ thân. Biết hai thần thai có thể giao cảm khi ở đủ gần, Thạch Hạo cố ý hôn Nguyệt Thiền để khiêu khích, khiến cả nàng lẫn chủ thân trên trời đều chấn động dữ dội."},{"chuong":529,"tieuDe":"Chiến Nguyệt Thiền","tomTat":"Chủ thân Nguyệt Thiền chặt đứt liên hệ với thứ thân, tụng tiên kinh ổn định đạo tâm rồi vận chuyển đại trận, triệu hoán mưa thiên thạch oanh kích hoàng cung Thạch quốc. Thạch Hạo mượn long khí, pháp kiếm và bảo ấn Nhân hoàng chém vỡ thiên thạch, đồng thời khôi phục các tầng trận pháp bảo vệ hoàng cung. Sự vắng mặt của Tiểu Tháp khiến hắn nhận ra mình đã quá ỷ lại ngoại lực, từ đó quyết tâm phải trở nên mạnh mẽ bằng chính bản thân. Sau khi giao Bằng Cửu chủ trì đại trận, Thạch Hạo cõng thứ thân Nguyệt Thiền, thi triển pháp môn Côn Bằng bay lên tầng mây nghênh chiến. Chủ thân Nguyệt Thiền tuyên bố muốn giết hắn để làm sáng tỏ đạo tâm, khiến hai bên bùng nổ một trận giao phong dữ dội bằng kiếm khí, bảo thuật và thần thông. Khi chủ thân phóng tiên hoàng đỏ rực nhằm tiêu diệt thứ thân, Thạch Hạo kịp thời né tránh, còn thứ thân vì bị ruồng bỏ đã quyết định hợp tác với hắn để bắt giữ chủ thân. Được sự trợ giúp ấy, Thạch Hạo lập tức mang theo ánh kiếm xông tới và thi triển bảo thuật kinh thế trấn áp đối phương."},{"chuong":530,"tieuDe":"Một Thân Hai Mặt","tomTat":"Đạo tâm bị quấy nhiễu khiến chủ thân Nguyệt Thiền mất tiên cơ, lần đầu bị kiếm khí của Thạch Hạo phá vỡ phòng ngự và làm bị thương kể từ khi xuất đạo. Sau khi hy sinh bức họa hỏa diễm để thoát khỏi cận chiến, nàng thi triển thần thông Chân Long, rồi kết hợp thêm Thần Hoàng bất tử để đối đầu với bảo thuật Côn Bằng của Thạch Hạo. Được thứ thân Nguyệt Thiền liên tục chỉ ra những khiếm khuyết trong truyền thừa của đối phương, Thạch Hạo phá giải thế long phượng hợp kích và nhiều lần đẩy chủ thân vào cảnh nguy hiểm. Khi thời cơ xuất hiện, hắn vận dụng lực Luân hồi từ Chí tôn cốt khiến chủ thân hóa thành trẻ nhỏ, nhưng nàng lập tức dùng Bổ Thiên thuật cùng đỉnh hoàng kim chống đỡ, còn chiếc đỉnh lại nhân đó phục hồi trạng thái gần như mới. Trong cuộc đối chất sau đó, thứ thân bác bỏ quan niệm rằng bị giết rồi tái sinh vẫn là cùng một người, đồng thời phản kháng địa vị phụ thuộc giữa hai thần thai có chung nguồn gốc. Thạch Hạo vì thế nhận ra cổ pháp phân tách chủ thân và thứ thân vốn không hoàn thiện, bởi hai ý thức độc lập đã hình thành thì không thể hoàn toàn hợp nhất như ban đầu. Hắn che giấu cuộc trao đổi, còn thứ thân xin thời gian suy diễn kế hoạch trấn áp chủ thân và cảnh báo rằng cả hai phải lập tức hợp lực vì đối phương tuyệt đối sẽ không để họ trốn thoát."},{"chuong":531,"tieuDe":"Chém Giết","tomTat":"Thạch Hạo giao chiến dữ dội với chủ thân Nguyệt Thiền trong khi thứ thân nằm trên lưng hắn, tuyên bố đã đoạn tuyệt với chủ thân và liên tục chỉ điểm nhược điểm của đối phương. Chủ thân tiếp dẫn thánh lực mặt trăng, hóa sinh chân long và thần hoàng đánh Thạch Hạo bị thương, nhưng hắn dùng Nguyên thủy chân giải, long khí hoàng cung và ngọc tỷ diễn hóa kim liên đại đạo để phản kích. Thạch Hạo tiếp tục phối hợp lôi điện Toan Nghê, kiếm ý của một cây cỏ và lực Côn Bằng, khiến chủ thân trọng thương rồi truy đuổi nàng qua trận pháp thiên thạch. Khi Chí tôn cốt không thể vượt qua khoảng cách kỳ dị trước mặt, hắn rút lui, còn chủ thân chữa thương và kích hoạt tám tòa đại trận cấp Thần đã bố trí sẵn. Sát trận đánh tan bóng người ở trung tâm, khiến chủ thân tưởng Thạch Hạo đã chết và thu lấy Hộp quý đồng thau đang giam thứ thân. Tuy nhiên, thứ bị hủy chỉ là thế thân trên Chí tôn cốt, còn chân thân Thạch Hạo ẩn trong thiên thạch. Chờ đối phương mất cảnh giác, hắn phá thạch xuất hiện cùng sức mạnh Luân hồi và phát động đòn đánh mang thần uy Chí tôn."},{"chuong":532,"tieuDe":"Oa Kiếp","tomTat":"Thạch Hạo kích phát Luân hồi từ Chí tôn cốt, dùng người tí hon cùng vô lượng thần văn áp chế các bảo thuật hộ thân của chủ thân Nguyệt Thiền. Nàng vận dụng Bổ Thiên Thuật và áo nghĩa hữu hối, thiêu đốt tiềm năng để phá bóng người Chí tôn, nhưng các phù văn còn lại vẫn khiến thân thể nàng trở về hình dáng một cô bé tám, chín tuổi. Trong trạng thái suy yếu, Nguyệt Thiền tiếp tục thiêu đốt lực Thần hồn và tiềm năng bị phong ấn nhưng vẫn bị Thạch Hạo áp đảo. Đòn tuyệt sát của nó đánh gãy toàn bộ xương nàng và làm nhiều pháp khí, trân vật rơi ra, song thể phách từng hấp thụ Kim thân dịch giúp nàng chưa chết. Một bình ngọc vỡ ra để lộ chân huyết Phượng hoàng, khiến giọt máu giao hòa với thân thể nàng và Hoàng kim đỉnh. Chí bảo thượng cổ thức tỉnh, thu Nguyệt Thiền vào trong, chịu công kích thay chủ rồi xuyên qua hư không bỏ chạy. Thạch Hạo thu các chiến lợi phẩm, trong đó có Hộp quý đồng thau, dùng Nhân hoàng ấn truy kích nhưng cuối cùng không thể ngăn chiếc đỉnh biến mất."},{"chuong":533,"tieuDe":"Được Bảo Thuật","tomTat":"Sau trận chiến trên hoàng cung, Thạch Hạo trở về trong tiếng tung hô Nhân Hoàng của dân chúng Hoàng đô, còn long khí ngày càng hội tụ quanh hắn. Khi kiểm kê chiến lợi phẩm, hắn tìm thấy Ngân hoàng vũ dùng để tế luyện Quạt Ngũ Cầm và Bổ Thiên Đan có khả năng cứu sống người vẫn còn một hơi thở. Thạch Hạo thả thứ thân Nguyệt Thiền khỏi Thế giới hộp báu; nàng tuyên bố đoạn tuyệt với chủ thân, đề nghị hợp tác và truyền cho hắn Phượng Phi Cửu Thiên, thức thứ nhất của bảo thuật Thần Hoàng. Dù nghi ngờ cổ pháp có vấn đề và kiên quyết từ chối tu pháp chủ thân–thứ thân, Thạch Hạo vẫn bắt đầu chuyên tâm tu luyện thức mới. Trong lúc chiến tích của hắn và tin tức về chủ thân Nguyệt Thiền lan khắp Hoang Vực, Tiểu Tháp trở lại rồi báo rằng mình sắp rời đi. Liễu Thần sau đó cũng từ biệt và chỉ cho Thạch Hạo vị trí hiện tại của Thạch thôn. Cuối cùng, Thạch Hạo dẫn thứ thân Nguyệt Thiền với thân phận tù binh cùng Tiểu Tháp trở về Thạch thôn."},{"chuong":534,"tieuDe":"Thế Ngoại Đào Nguyên","tomTat":"Vợ chồng Thạch Tử Lăng theo Thạch Hạo tới tổ địa sau khi chứng kiến hình ảnh uy nghiêm của Liễu Thần tại Trung ương Thiên cung. Liễu Thần mở thông đạo xuyên hư không đưa mọi người tới Thạch thôn và tiết lộ rằng toàn bộ khu sơn thủy mười dặm đã được chuyển sang một vùng đất giàu linh mạch. Dân làng vui mừng đón Thạch Hạo trở về, còn cha mẹ cậu hành đại lễ cảm tạ tộc trưởng cùng những người đã nuôi dưỡng con trai mình. Thứ thân Nguyệt Thiền và Tần Hạo kinh ngạc trước cây đào bạc gần thành thánh dược, trận pháp bảo vệ cùng nội tình vượt xa vẻ ngoài giản dị của ngôi làng. Thạch Hạo hội ngộ những người bạn thuở nhỏ và nhận ra Đại Bằng, Tiểu Thanh, Tử Vân cùng Tiểu Bạch đều đã được Liễu Thần gột rửa huyết thống. Tiểu Bạch đã mọc cánh và có dấu hiệu tiến hóa thành Tiên mã, trong khi Thứ thân Nguyệt Thiền dần nhìn thấy phương diện ngoan hiền của Thạch Hạo khi cậu ở quê nhà. Cuối chương, mọi người cưỡi các dị cầm tiến vào sâu trong núi để xem một trận chiến dữ dội, nơi xuất hiện bóng người được thần hỏa bao phủ."},{"chuong":535,"tieuDe":"Thần Thôn","tomTat":"Trong Chiến vực Thần ma, Bóng Lông và Con chim đỏ nhỏ giao chiến quyết liệt, đồng thời để lộ dấu hiệu đã bước đầu nhen nhóm Thần hỏa. Thạch Hạo trở về Thạch thôn, biết Liễu Thần đã phục hồi Bóng Lông, gột rửa thân thể cho gia đình Thanh Lân Ưng và chuẩn bị sức tự vệ cho thôn trước khi rời đi. Hắn dễ dàng trấn áp lời thách đấu của Đại Hồng Điểu rồi cùng Nguyệt Thiền và Tần Hạo đoàn tụ với dân làng, trong lúc những chuyện nghịch ngợm thời nhỏ bị bạn bè kể lại. Bóng Lông tiết lộ sơn bảo là hộp thiên cốt chứa kinh văn cấm kỵ có thể tổ hợp thần thông và quy nhất bảo thuật, nhưng chí bảo đã thất lạc sau khi nó trọng thương. Trong đêm sum họp, Thạch Hạo phân phát nhiều vật phẩm cùng lượng lớn hỏa dịch cho người trong thôn. Dưới cây liễu, Liễu Thần và Tiểu Tháp cho biết họ sẽ rời đi sau trận chiến phong Thần cuối cùng của tám vực, đồng thời khuyên Thạch Hạo tiến vào thượng giới vì pháp tắc hạ giới không hoàn chỉnh. Họ còn hé lộ rằng phần lớn thượng giới vẫn chưa được khám phá và đích đến của Liễu Thần có thể nằm sâu trong những khu vực thần bí ấy."},{"chuong":536,"tieuDe":"Thượng Giới Bí Hiểm","tomTat":"Tiểu Tháp tiết lộ rằng vùng sinh sống của vô số chủng tộc chỉ là một góc nhỏ của thượng giới, còn bên ngoài tồn tại những khu vực thần bí đủ sức giết cả bá chủ và những đoàn thám hiểm hùng mạnh. Nó kể về nguồn gốc của linh căn gần Dược đô, thảm họa của hai thư viện cổ và đoàn tiếp ứng từng tìm cách đưa trứng đá chân long ra ngoài. Liễu Thần xác nhận thời thái cổ từng phá cửa ải sinh tử và tiến vào một con đường bí hiểm, khiến khả năng cánh cửa nguyên thủy dẫn tới vùng sâu ấy càng trở nên rõ ràng. Tiểu Tháp cùng Liễu Thần dự báo tám vực sắp trải qua trận chiến phong Thần cuối cùng, sau đó hai giới sẽ bị cắt đứt và hạ giới bước vào một thời kỳ phồn thịnh nhưng vẫn có nguy cơ bị coi là nơi nuôi đại dược. Phẫn nộ trước số phận của tám vực, Thạch Hạo quyết định lên thượng giới để tìm hiểu đại đạo, pháp tắc đầy đủ và thiên địa gần hoàn mỹ. Tiểu Tháp đề nghị nó gia nhập học viện Thiên tiên, nơi quy tụ nhiều thiên kiêu và sơ đại. Cuối chương, Liễu Thần hiện nhân thân áo trắng giữa ba ngàn giới, nói về sự siêu thoát trên trời xanh và hẹn Thạch Hạo một ngày gặp lại tại đó. Thạch Hạo nhớ lại lời tộc trưởng kể về lúc Liễu Thần giáng xuống Thạch thôn trong tình trạng cháy đen gần chết khô, càng nhận rõ con đường phía trước của Liễu Thần chứa đựng một lựa chọn khó lường."},{"chuong":537,"tieuDe":"Bảy Mươi Hai Biến","tomTat":"Trong những ngày cuối bình yên tại Thạch thôn, Thạch Hạo truyền pháp môn chim thần cho Tử Vân, Đại Bằng và Tiểu Thanh, còn Liễu Thần dựng một tế đàn mới vừa bảo vệ thôn vừa truyền tống cỡ lớn. Thạch Hạo sau đó mặc chiến y Bất diệt kim thân giao đấu với Bóng Lông trong Chiến vực Thần ma, dùng Trùng đồng nhìn xuyên Thân hóa vạn ngàn và tìm ra chân thân đối thủ. Hai bên thống nhất chỉ trao đổi phần truyền thừa cần thiết: Bóng Lông truyền Bảy mươi hai biến, còn Thạch Hạo trao phần biến hóa thích hợp trong pháp môn Côn bằng. Thạch Hạo bước đầu luyện bí thuật, hóa thành nhiều sinh linh và vật thể, đồng thời nhận ra hình thái biến hóa vẫn không thể vượt quá giới hạn thực lực của bản thân. Nó đưa Thạch Đại Tráng, Bì Hầu, Hổ Tử, Thanh Phong, Tần Hạo và Thứ thân Nguyệt Thiền trở lại Thạch Quốc rồi sắp xếp con đường rèn luyện cho những người bạn trong thôn. Nửa tháng sau, bầu trời nứt toạc và vô số bóng người quấn tia điện xuất hiện; Tiểu Tháp cảnh báo các thế lực trên trời đang chuẩn bị thiên binh để lật đổ Hoang vực. Liễu Thần hiện thân tại trung ương thiên cung, xác nhận đại chiến Phong thần đã tới và sẽ hoàn toàn kết thúc trong vài ngày."},{"chuong":538,"tieuDe":"Tâm Nguyện Chưa Xong","tomTat":"Trước trận chiến Phong thần, thế lực Minh thổ mở đường vượt giới, triệu hoán vô số anh linh và cường giả tới thăm dò Hoang vực. Liễu Thần dùng cành liễu vàng mang dương khí cùng lôi đình tịnh hóa lực lượng xâm nhập, đồng thời đánh Hỗn độn thi bị thương và buộc nó rút lui. Tiểu Tháp xin Liễu Thần trợ giúp đoạt lại thân tháp tầng thứ hai, còn Liễu Thần dự định kết thúc nhân quả với hai kẻ liên quan tới quá khứ trước khi bước vào cánh cửa nguyên thủy. Dù biết vẫn còn đường đăng thiên, Thạch Hạo quyết định ở lại hạ giới để thu xếp việc kế vị Thạch quốc và chuẩn bị cho Thạch thôn. Liễu Thần giải thích rằng thiên Thần dẫn của Nguyên thủy chân giải còn thiếu Vạn linh đồ đã vỡ trên Thiên cốt, trong khi cảnh giới hiện tại của Thạch Hạo chưa đủ để tự suy diễn trọn vẹn. Khi các vực liên tiếp xuất hiện khe nứt và hàng vạn thiên binh giáng xuống Huyền vực, Thạch Hạo từ chối lời mời tụ hội của các tinh anh tám vực. Cậu nhờ Liễu Thần tìm lại hạt giống hồ lô của Tế Linh Bổ Thiên các, rồi chứng kiến dây leo truyền thừa được tìm thấy và bảo vệ bằng trận pháp. Ba ngày sau, thiên địa hóa thành màu máu, báo hiệu trận chiến Phong thần chính thức bắt đầu."},{"chuong":539,"tieuDe":"Liễu Thần Vô Địch","tomTat":"Liễu Thần hóa thành hình người áo trắng, từ biệt Thạch Hạo rồi bước ra khỏi hoàng cung lên con đường của chính mình. Bầu trời Hoang vực nứt vỡ, hoàng tuyền từ Minh thổ tràn xuống mang theo thi thể và khung xương, Tiểu Tháp suy đoán những kẻ thọ nguyên gần cạn từ thượng giới đang liều lĩnh xuống hạ giới tìm tạo hóa. Liễu Thần đẩy hoàng tuyền trở lại thượng giới rồi phóng một trăm lẻ tám cành hoàng kim tiêu diệt Hỗn độn thi — vị bá chủ cấp giáo chủ mang Bảo luân Minh giới và mảnh Minh thổ xâm nhập. Bất lão Thiên tôn đồng thời hiện đủ năm chân thân Ngũ hành vây công, Liễu Thần vận Côn Bằng bảo thuật biến vô số lá thành Côn Bằng tiêu diệt hai chân thân, buộc ba thân còn lại phải rút lui. Giáo chủ Tây Phương giáo hiện thân chặn Tiểu Tháp không cho tham chiến. Đạo nhân Âm dương mang tòa tháp hai tầng xuất hiện, Tiểu Tháp lao tới tranh đoạt tòa tháp, còn Liễu Thần giao chiến cận thân rồi dùng pháp ấn hợp nhất thiên địa phóng chùm sáng vĩnh hằng đánh nổ đạo nhân."},{"chuong":540,"tieuDe":"Cuộc Chiến Bá Chủ","tomTat":"Liễu Thần kết pháp ấn mang khí đại đạo vô thượng, đánh tan thân thể rồi tiêu diệt nguyên thần của đạo nhân Âm dương, khiến vị bá chủ cổ xưa hình thần đều diệt. Thân tháp hai tầng vì thế trở thành vật vô chủ, kéo Tiểu Tháp, Giáo chủ Tây Phương giáo, Hắc Kim Tước và người nắm giữ Luân Hồi Bàn vào một cuộc tranh đoạt dữ dội. Trong khi cường giả không tay cưỡi trâu, ba chân thân của Bất Lão Thiên Tôn và chủ nhân chiếc chuông lớn cùng kiềm chế Liễu Thần, Ngũ Hành Sơn cùng nhiều luồng pháp tắc đánh tan ý chí phản kháng trong thân tháp. Liễu Thần hiển hóa ba ngàn giới, dung hợp những con đường mình từng đi và cưỡng ép xông vào trung tâm hỗn chiến. Sau khi dùng chưởng đánh lõm chiếc chuông cổ hoàn chỉnh, Liễu Thần điều khiển thần thụ xanh biếc xuyên vào miệng chuông và kéo thân tháp hai tầng ra ngoài. Phần thân thể thất lạc được trao lại cho Tiểu Tháp, khiến nó vui mừng dùng hào quang cùng khí hỗn độn bắt đầu quá trình dung hợp."},{"chuong":541,"tieuDe":"Cánh Cửa","tomTat":"Trước sự vây công của các bá chủ thượng giới, Liễu Thần triệu hiện cánh cửa nguyên thủy để thu nhận những luồng sáng giết chóc từ sát trận thứ tư. Những chiếc lá liễu được bố trí từ trước hóa thành trận kỳ, giúp Liễu Thần bắt giữ một bá chủ rồi ném người này vào cánh cửa, khiến nó càng thêm thần thánh. Để tránh làm hại sinh linh hạ giới, Liễu Thần chuyển toàn bộ chiến trường vào hỗn độn, còn Tiểu Tháp và các bá chủ cũng rời khỏi Hoang vực. Thạch Hạo dùng viên Trùng đồng theo dõi cuộc chiến, đứng chờ nhiều ngày nhưng vẫn không nhận được tin tức về kết quả. Sau đó, Bằng Cửu báo rằng chủ thân Nguyệt Thiền, Ma nữ và nhiều hậu duệ thượng giới đang tụ hội trên một tòa đạo sơn trong cảnh nội Thạch quốc. Dù được cảnh báo về sát cơ tiềm ẩn, Thạch Hạo vẫn bố trí phòng bị trong cung rồi lên đường dự hội để dò hỏi tình hình đại kiếp."},{"chuong":542,"tieuDe":"Tranh Nhau Lôi Kéo","tomTat":"Thạch Hạo tới Hạc Minh sơn xem những hình khắc cổ và được Bích Cổ tiết lộ rằng Bồ Ma thụ vốn đến từ thượng giới, từng tự phế để tránh kiếp và có thể đang chờ tái sinh. Đi sâu vào vùng núi, nó gặp nhiều thiên tài đến từ thượng giới và tám vực, phần lớn đều chủ động kết giao nhưng cũng có người âm thầm mang địch ý. Qua cuộc trò chuyện với Lam Vũ, Thủy Nguyệt và những người khác, Thạch Hạo hiểu thêm về pháp tắc viên mãn cùng vô số thiên kiêu, sơ đại tại thượng giới, từ đó nảy sinh khát vọng tranh phong dù chưa thể buông bỏ chấp niệm ở hạ giới. Học viện Trục Lộc, học viện Sinh Mệnh và Xích hoàng cung lần lượt mời nó gia nhập, hứa bảo vệ hoặc dùng Niết bàn pháp giúp nó lột xác. Ma nữ sau đó xuất hiện, đề nghị Thạch Hạo gia nhập Bổ Thiên giáo rồi đối diện Nguyệt Thiền trong bầu không khí đầy địch ý, khiến các thiếu nữ khác phải đứng ra hòa giải. Ma nữ nhắc lại lời đồn Thạch Hạo từng trấn áp Nguyệt Thiền và thúc giục hai người kính rượu nhau. Thạch Hạo cùng Nguyệt Thiền vẫn mỉm cười chạm chén trước đám đông, che giấu ẩn tình liên quan tới một Nguyệt Thiền khác từng bị nó trấn áp."},{"chuong":543,"tieuDe":"Phong Ba Buổi Tụ Hội","tomTat":"Tại buổi tụ hội trên Hạc minh sơn, Ma nữ khơi lại lời đồn Thạch Hạo từng giam giữ Nguyệt Thiền, nhưng chủ thân Nguyệt Thiền vẫn bình thản và tấu đàn dẫn động đạo vận thiên địa. Trong lúc luận đạo, Bích Cổ, Lam Vũ và Oánh Oánh giúp Thạch Hạo nhận ra rằng nghiên cứu cốt văn bách tộc cũng có thể mở ra đại đạo, thay vì chỉ chuyên chú Pháp môn Côn Bằng. Hồng Hoàng mời Nguyệt Thiền trao đổi Bảo thuật Chân Hoàng, còn Thạch Hạo tiết lộ mình cũng biết một phần cổ thuật này. Khi Thạch Hạo hỏi về cuộc chiến của các đầu sỏ, Thủy Nguyệt cho biết chiến trường dường như đã tiến vào hỗn độn, khiến hắn lo lắng cho tòa cốt tháp. Một truyền nhân trẻ tuổi Minh thổ sau đó xuất hiện, tuyên bố tòa tháp đã bị đánh vào cánh cửa nguyên thủy và công khai muốn giết Thạch Hạo để đoạt thiên cốt. Cường giả trẻ tuổi của Bất Lão sơn lập tức ngăn cản, đòi đưa Thạch Hạo lên thượng giới xử trí vì huyết mạch của hắn. Hai bên đối đầu gay gắt, trong khi phía sau mỗi người đều có một sinh linh đã nhen nhóm thần hỏa làm chỗ dựa."},{"chuong":544,"tieuDe":"Thần Hỏa Bập Bềnh","tomTat":"Một thần phó xương khô của Minh thổ và một vị Thần mang tinh khí ngũ hành của Bất Lão sơn giáng lâm, giao chiến bằng pháp bảo cùng hai loại vực đối nghịch để tranh quyền xử trí Thạch Hạo. Trước áp lực từ các sinh linh đã nhen nhóm Thần hỏa, Thạch Hạo nói với Ma nữ rằng mình sẽ chạy thay vì đối đầu trực diện, còn Ma nữ nghi ngờ Bổ Thiên giáo cũng đã đưa viện binh tới. Cô gái áo đen và Hướng nhật ma quỳ của Ma Quỳ viên chặn đường, khiến Minh thổ, Bất Lão sơn và Ma Quỳ viên hình thành thế chân vạc quanh thiên cốt. Ba truyền nhân trẻ tuổi lần lượt thúc giục cường giả phía sau ra tay hoặc đề nghị bàn cách lấy cốt, trong khi nhiều phe khác cũng bắt đầu gọi viện binh và tìm cách chiêu dụ Thạch Hạo. Khi ba sinh linh Thần hỏa cùng ngăn đường, Thạch Hạo dùng một thủ đoạn không lộ dao động pháp tắc hay thần năng để định trụ rồi đạp bay cả ba. Hắn tiếp tục tế thiên cốt, dùng bảo thuật khiến cô gái Ma Quỳ viên, truyền nhân Minh thổ và người trẻ tuổi Bất Lão sơn nhanh chóng già yếu. Cuối cùng, Thạch Hạo giẫm lên hai người và túm truyền nhân Minh thổ liên tiếp đánh vào mặt, tạm thời áp đảo những kẻ muốn đoạt cốt."},{"chuong":545,"tieuDe":"Không Nói Thành Lời","tomTat":"Thạch Hạo liên tục đánh Minh nhân trẻ tuổi vì thái độ khinh miệt sinh linh hạ giới, khiến đối phương gãy răng, gãy xương mũi, trật quai hàm và chịu nhục trước đám đông. Trước khi hiệu lực khiến các đối thủ già yếu chấm dứt, hắn đánh gãy minh cốt của Minh nhân và đạp nứt xương người trẻ tuổi Bất Lão sơn để tước sức chiến đấu. Cô gái áo đen khôi phục tuổi xuân và thần lực, dùng tóc, rễ cây cùng thái dương đen phản kích, nhưng Thạch Hạo dựa vào thân thể, chiến y Bất diệt kim thân và Bảo thuật Côn bằng để phá tan công kích rồi phong ấn nàng. Hắn ép nàng hiện nguyên hình thành cây hướng dương đen, ăn thử hạt và phát hiện chỉ vài hạt đã có thể nhanh chóng bổ sung tinh khí. Sau đó, Thạch Hạo thu toàn bộ hạt của cây Ma quỳ đã nhen nhóm Thần hỏa vào đỉnh ngọc, khiến người của Ma quỳ viên chịu thất bại nặng nề tại hạ giới. Thu hoạch xong, hắn phát hiện một cường giả hệ Thực vật hình nho trong nhóm người ở xa và lập tức đuổi theo để lấy quả."},{"chuong":546,"tieuDe":"Phong Thần","tomTat":"Các linh thân của những cường giả đã nhen nhóm Thần hỏa vây công Thạch Hạo, buộc hắn vận dụng pháp môn Côn Bằng né tránh và giả vờ sở hữu thuật định thân. Định thần phù hắn tung ra chỉ đốt cháy một phần dây leo rồi hóa tro, khiến đối phương nhìn thấu màn phô trương và tiếp tục khép vòng vây. Trong tình thế nguy hiểm, Thạch Hạo âm thầm cầu viện Sinh linh Bất diệt, nhờ đó bốn linh thân bị cố định và những chân thân dùng trận đài cùng Phá không phù bỏ trốn cũng bị bàn tay vàng bắt trở lại. Sinh linh Bất diệt tuyên bố hạ giới từ nay không còn Thần rồi nuốt hàng loạt cường giả Thần hỏa thuộc Minh thổ, Bất Lão sơn, Ma quỳ và Hắc kim tước. Thạch Hạo chém những linh thân còn sót, trong đó có Minh nhân và Ma quỳ hóa thành cô gái áo đen, nhưng tha người trẻ tuổi Bất Lão sơn vì nghi người này có quan hệ huyết thống với mẹ mình. Sau một lần trêu chọc chủ thân Nguyệt Thiền không thành, hắn biết Sinh linh Bất diệt đã rời đi Phong thần. Sinh linh Bất diệt tiếp tục giáng lâm Bổ Thiên giáo và Tây Phương giáo để bắt các thần cùng kim thân, khiến cuộc thanh trừng lan khắp hạ giới và làm cả thế gian chấn động."},{"chuong":547,"tieuDe":"Diệt Thần","tomTat":"Sinh linh Bất diệt hiện chân thân khổng lồ, đi khắp tám vực săn bắt những cường giả thượng giới đã nhen nhóm Thần hỏa và đặc biệt thanh trừng nhân mã của Bất Lão sơn, Tây Phương giáo cùng các đại giáo từng trấn áp mình. Tin tức khiến cuộc tụ hội tại Hắc Minh sơn tan rã, còn Thạch Hạo trở về hoàng cung Thạch quốc trấn an Bằng Cửu nhưng vẫn lo những kẻ lọt lưới sẽ gây họa. Sinh linh Bất diệt cho biết các bá chủ đã trở lại thượng giới khi thời hạn kết thúc, trong khi Liễu Thần và Tiểu Tháp đã dùng tế phẩm cùng vài bá chủ dò đường rồi tiến vào cánh cửa nguyên thủy. Linh thân của hắn vừa bước qua cánh cửa đã hóa thành máu, khiến an nguy của Liễu Thần và Tiểu Tháp càng khó xác định. Mảnh tinh phiến do Liễu Thần đưa ra được tiết lộ là một phần của Hỗn độn bảo giám, đủ sức soi chiếu tám vực và tìm những sinh linh đã nhen nhóm Thần hỏa. Nhờ kỳ bảo này, Sinh linh Bất diệt phát hiện các đối thủ đang ẩn náu, tạm phong kín những cứ điểm thông lên thượng giới và hoàn tất cuộc phong sát. Sau khi báo rằng hạ giới sẽ được yên ổn một thời gian, hắn từ chối lưu lại, cảnh báo Thạch Hạo không được mượn uy danh của mình rồi phá không lên thượng giới báo thù."},{"chuong":548,"tieuDe":"Tâm Nguyện Của Tiểu Thạch","tomTat":"Sau khi sinh linh Bất diệt quét sạch các cường giả đã nhen nhóm Thần hỏa, Thạch Hạo vẫn lo lắng vì Liễu Thần và Tiểu Tháp đã bước vào cánh cửa nguyên thủy mà chưa rõ sống chết. Nó quyết định thu xếp mọi việc ở hạ giới rồi tiến lên thượng giới tìm kiếm đại đạo và truy tìm hai người. Thạch Hạo cân nhắc giao Thạch quốc cho Thanh Phong, nhưng nhận ra người em còn quá nhỏ, trong khi những người từ Thạch thôn đang dần thích nghi với quân đội và cuộc sống bên ngoài. Nó xử lý các chư hầu chống đối bằng cả trừng phạt lẫn khoan dung, sai Chiến Vương truy sát kẻ bỏ trốn và tự mình diệt phản nghịch, khiến Thạch quốc trở lại thống nhất. Trở về phế tích Bổ Thiên Các, Thạch Hạo tưởng niệm những người đã hy sinh, dựng bia khắc tên môn phái và tuyên bố sẽ tái lập Bổ Thiên Các trước khi rời hạ giới. Kiếm gãy màu đen lập tức phát sinh dị động, tự ngân vang và bay lượn như hưởng ứng tâm nguyện ấy. Sau đó, Thạch Hạo đến bộ lạc Tiêu thị gặp lại Tiêu Thiên và mời người đồng môn cũ cùng quét sạch kẻ địch, xây dựng lại môn phái, khiến Tiêu Thiên xúc động."},{"chuong":549,"tieuDe":"Thạch Hạo Trở Nên Điên Cuồng","tomTat":"Thạch Hạo và Tiêu Thiên nhớ lại thảm họa diệt môn rồi quyết định cùng trùng kiến Bổ Thiên Các. Họ tập hợp Chu Vũ Hào, Ngạn Tâm, Phiêu Tuyết, tới học viện Trục Lộc tìm Hạ U Vũ và nhận thêm sự tham gia của Nữ Chiến Thần. Thạch Hạo tiết lộ Tế Linh vẫn có khả năng tái hiện, đồng thời để các đồng môn âm thầm xây dựng trên phế tích cũ còn mình công khai thu hút kẻ địch. Nó xác định những thế lực và chí cường giả từng góp phần diệt môn, sau đó chọn Thác Bạt gia làm mục tiêu thanh toán đầu tiên. Thạch Hạo phá nát sơn môn cùng đại trận, rồi giết người đàn ông trung niên từng sát hại Thành sư huynh. Khi một đệ tử sống sót chỉ ra lão tổ Thác Bạt từng đánh lén Mộ Viêm đến mức phải tự bạo, Thạch Hạo nổi giận và dùng Bảo thuật Côn Bằng đánh nổ đối phương cùng mọi pháp bảo phòng thủ. Nó tiếp tục tiến sâu vào cổ địa, nghiền nát những cường giả Thác Bạt cản đường và thiêu xác họ thành tro."},{"chuong":550,"tieuDe":"Diệt Trừ","tomTat":"Thạch Hạo hóa Côn Bằng đánh vào trụ địa Thác Bạt tộc, sau đó dùng chiến xa hoàng kim và pháp kiếm thần linh của Thạch quốc phá tan đại trận Tinh đấu đã hao mòn. Lão tổ Thác Bạt đem đèn bạc cấp thần linh ra chống cự nhưng bị thần kích trấn quốc áp đảo, rồi chính lão cũng bị pháp kiếm chém chết. Thạch Hạo tiếp tục dùng kiếm khí cỏ xanh thanh toán những kẻ từng tham gia tàn sát Bổ Thiên Các, song vẫn tha phụ nữ, trẻ nhỏ và người không liên can. Nhóm của nó truy đến bí thổ dự phòng, tiêu diệt số cao thủ còn ẩn náu và khiến Thác Bạt tộc mất toàn bộ căn cơ tu hành. Sau đó đoàn vượt hơn mười vạn dặm tới Sư Sơn, nơi Cửu đầu sư tử được xác nhận có tên thật là Kim Hoành và nhiệt tình tiếp đón người đại ca kết bái. Cửu Linh Vương cho biết mình đã đột phá Tôn giả sau đại kiếp, nhưng Thạch Hạo còn cảm nhận được một khí tức cùng cấp khác trong núi. Kim Hoành giận dữ tiết lộ rằng một cường giả từ thượng giới đang ngủ trong động cổ của Sư Sơn, khiến cả đoàn lập tức cảnh giác."},{"chuong":551,"tieuDe":"Quy Tôn","tomTat":"Kim Hoành kể rằng một Tôn giả từ thượng giới đã tới lãnh địa Hoàng kim sư tử, chiếm bảo địa của Cửu Linh Vương và muốn chọn cường giả trong tộc làm tọa kỵ cho thần thánh. Thạch Hạo quyết định can thiệp, giao chiến với Huyền Quy bằng chiến y Bất diệt kim thân, thân pháp và lực Côn Bằng, cuối cùng đánh xuyên sức phòng ngự từ mai rùa khiến đối phương phải đầu hàng. Huyền Quy khai mình đến từ Tử Phủ sơn, vốn chủ động nhận thay Cẩm Lý nhiệm vụ xuống hạ giới tìm tọa kỵ, rồi bị Thạch Hạo thu nhỏ, ép đi theo và đặt tên Tam hắc. Sau khi xác nhận với Kim Hoành rằng mình đang chuẩn bị lên thượng giới, Thạch Hạo dẫn Tiêu Thiên, Hạ U Vũ, Ngạn Tâm và Chu Vũ Hào cưỡi Tam hắc tới Thần sơn Nam Vẫn. Đoàn người dùng chiến xa thần khí và sự chỉ dẫn của Đả Thần Thạch để vượt biển sương mù cùng trận pháp, sau đó đi theo một giọng nói già nua tới ngọn núi đen. Trên đỉnh núi, họ gặp một ông lão tóc trắng đang đốt giấy cúng bên những ngôi mộ chôn các thần linh sống sót từ thời thượng cổ. Việc vừa tới Nam Vẫn đã được dẫn thẳng tới nghĩa địa thần linh khiến Thạch Hạo cảnh giác và nghi ngờ dụng ý của người tiếp đón."},{"chuong":552,"tieuDe":"Nam Vẫn","tomTat":"Thạch Hạo cùng người của Bổ Thiên các tới Thần sơn Nam Vẫn và gặp một ông lão từng nhen nhóm Thần hỏa. Nam Vẫn kể rằng lão đã chủ động đánh tan Thần hỏa để sống qua đại kiếp, sau đó nhờ thánh dược mới khôi phục tới cảnh giới Tôn giả. Qua tinh thạch ghi hình, Thạch Hạo xác nhận kẻ từng tấn công Bổ Thiên các đã chết hoặc bị bắt nên từ bỏ ý định trút giận lên những người vô tội, đồng thời nhận Hoàng Văn Thạch do Nam Vẫn trao tặng. Đoàn người tiếp tục tới Nghi sơn, biết toàn bộ cao thủ nơi đây đã bị đại kiếp trấn áp, còn Tiêu Thiên và Hạ U Vũ quyết tâm trùng kiến Bổ Thiên các. Tại Tây Lăng, họ tìm hiểu nguồn gốc Thú sơn rồi tiến vào nghĩa địa Thái Cổ, nơi cảnh vật đột ngột biến thành một thế giới man hoang đầy hung thú chân thực. Tiêu Thiên bị Viêm Mãng va trúng tới mức gần chết, khiến Huyền Quy nhận định Tây Lăng có thể đã diễn hóa thành một thế giới riêng. Trong lúc Thạch Hạo bảo vệ đoàn người, hai khối tàn cốt Nguyên Thủy Chân Giải trên người nó phát sáng và cộng hưởng như đang kêu gọi một tồn tại chưa rõ."},{"chuong":553,"tieuDe":"Tây Lăng Giới","tomTat":"Thạch Hạo ghép hai khối tàn cốt Vạn Linh đồ và nhận thấy chúng rung lên, phát sáng, từ đó nghi mảnh còn thiếu của Nguyên Thủy Chân Giải đang nằm trong nghĩa địa Tây Lăng. Tam hắc giải thích ý chí của vô số Thần Vương, Thiên Thần và sinh linh Thái Cổ đã đan xen, khiến nghĩa địa tự diễn hóa thành một thế giới nửa hư nửa thật tương tự Hư Thần giới. Dù Thạch Hạo cảnh báo nguy hiểm, Hạ U Vũ cùng những người khác vẫn quyết định tiếp tục thăm dò và nhìn thấy bia đá khắc tên Tây Lăng Giới. Trên đường đi, một anh linh hình báo chỉ vô tình va trúng cũng khiến Tam hắc thổ huyết, cho thấy sức mạnh đáng sợ của các sinh linh nơi đây. Cả nhóm sau đó phát hiện Thiểm Điện thụ, nhưng việc Tam hắc hái bốn Thiểm Điện quả đã kinh động đàn Thiểm Điện trùng, khiến nó bị đánh vỡ mai và xuyên thủng vai. Thạch Hạo cứu Tam hắc rồi dùng pháp môn Côn Bằng đưa mọi người tháo chạy, trong khi con sâu lớn nhất vẫn tiếp tục truy sát. Hoàng Điệp bất ngờ thức tỉnh và phát tiếng kêu khiến con sâu run rẩy quay về, giúp cả nhóm giữ được bốn quả dù chưa ai dám xác nhận chúng có thể ăn hay không."},{"chuong":554,"tieuDe":"Tạo Hóa Nhỏ","tomTat":"Huyền Quy thử Thiểm Điện quả chưa chín và bị lôi điện làm cháy đen, còn Thạch Hạo dùng bảo thuật Toan Nghê để luyện hóa năng lượng trong quả và thu nhận phù văn Lôi Đạo. Tạo hóa này đi kèm tử quang nguy hiểm, khiến sinh cơ của cả Thạch Hạo lẫn Huyền Quy nhanh chóng suy kiệt. Tôn giả Bạch Hổ nhân cơ hội dẫn Sư tử già và Voi lớn tập kích, dùng kiếm khí canh kim cùng Sư tử Hống áp đảo pháp khí của nhóm Tiêu Thiên. Xương ngực Thạch Hạo sau đó phát ra sức mạnh Luân Hồi, đẩy tử quang khỏi cơ thể hắn và cứu Huyền Quy. Phù văn Thiểm Điện dung hợp với bảo thuật Toan Nghê giúp lôi pháp của Thạch Hạo tăng mạnh, cho phép hắn giết cả ba thủ lĩnh Thú sơn. Thạch Hạo cùng Huyền Quy quay lại Tây Lăng giới, thanh trừ những cường giả Thú sơn còn sót rồi phát hiện một tế đàn chất đầy xương cốt. Nguyên Thủy Chân Cốt trong tay hắn phát sáng và cảm ứng với một khối cốt nhỏ trắng bóng như ngọc trên tế đàn."},{"chuong":555,"tieuDe":"Vạn Linh Đồ","tomTat":"Thạch Hạo tìm thấy mảnh Nguyên Thủy Chân Cốt cuối cùng trên một tế đàn đá đen giữa Tây Lăng và dùng bảo thuật hóa chim tước lấy nó từ xa. Hành động này khiến tròng mắt dính máu thức tỉnh, tế đàn phát ra gợn sóng đen và hàng loạt sinh linh cổ đồng loạt truy sát, làm Thạch Hạo cùng Huyền Quy bị thương nặng. Không thể thoát hẳn bằng Pháp môn Côn Bằng, Thạch Hạo đưa Huyền Quy vào tiểu thế giới trong hộp quý đồng thau, nơi thứ thân Nguyệt Thiền đang bị giữ, rồi cả hai dùng hạt Ma Quỳ chữa thương. Ba mảnh chân cốt tự cảm ứng và hợp nhất thành Vạn Linh đồ, sau đó tự hiển hóa bức tranh vạn linh khiến xương sọ thủy tinh cùng gợn sóng đen đang phá hộp báu phải rút lui. Thạch Hạo mang Vạn Linh đồ an toàn rời Tây Lăng nhưng chỉ kể sơ lược tai biến cho Tiêu Thiên, Hạ U Vũ và những người khác, cố ý giấu thu hoạch quan trọng này. Qua việc hỏi các sinh linh tại Thú sơn, nó biết Tây Lăng vốn chỉ là một nghĩa địa và mới gần đây tự thành một giới, vì vậy quyết định không quay lại rồi dẫn mọi người rời đi."},{"chuong":556,"tieuDe":"Không Muốn","tomTat":"Thạch Hạo cùng các đồng môn tưởng niệm những người đã mất tại phế tích Bổ Thiên các, trong khi những người sống sót bắt đầu dọn dẹp để xây dựng lại sơn môn. Trở về Hoàng đô, hắn mở tiệc tiễn biệt, gặp lại bạn cũ từ Bách Đoạn sơn và giới thiệu nhóm Đại Tráng với các đồng môn để họ có thể giúp đỡ nhau sau khi hắn rời đi. Trước nỗi lo hai giới cách biệt và cố nhân có thể không còn khi mình trở về, Thạch Hạo nói rõ khát vọng tiến lên đại đạo, phản kháng trật tự của các bá chủ thượng giới và tìm lại Liễu Thần, sau đó củng cố đạo tâm và khẳng định bản thân không hối hận. Hắn cân nhắc truyền ngôi cho Thanh Phong để bù đắp những khổ nạn người em từng chịu, nhưng vẫn lo tính cách Thanh Phong quá mềm mỏng và cũng không muốn đặt gánh nặng lên Tần Hạo nên chưa quyết định. Thạch Hạo dùng Chí Tôn cốt tịnh hóa tử khí trong một phần Thiểm Điện quả, vận chuyển Bảo Thuật của Toan Nghê hộ pháp, giúp Thanh Phong hình thành nền tảng Lôi đạo. Khi biết Tần Hạo đã để thư trở về Bất Lão sơn, hắn mang Huyền Quy phá không tới Huyền vực, hóa thành muỗi và nhờ Đả Thần Thạch chỉ dẫn để vượt qua trận pháp. Tại tế đàn cổ đang phát sáng, Tần Hạo tuyên bố sẽ đi con đường riêng và từ chối trở lại Thạch quốc, còn Thạch Hạo kinh động khi nhận ra tế đàn vẫn có thể liên hệ với thượng giới."},{"chuong":557,"tieuDe":"Kế Hoạch Phục Sinh Chí Tôn","tomTat":"Thạch Hạo bí mật quan sát tế đàn đỏ thắm tại Bất Lão sơn, nhận ra nơi này liên hệ với thượng giới và đang dẫn hình chiếu của một khối cốt thần bí vào cơ thể Tần Hạo. Không thể thay đổi lựa chọn của em trai, nó tặng Tần Hạo một quả Thiểm Điện đã được tịnh hóa tử khí rồi hóa thành phi trùng rời đi, sau đó qua hoàng cung trở về Thạch thôn. Thạch Tử Lăng và Tần Di Ninh từ Huyền vực trở lại, cho biết dòng dõi của Tần Di Ninh đã thắng cuộc phân tranh tại Bất Lão sơn thượng giới và tiết lộ nguồn gốc khối cốt. Máu trên khối cốt đã được luyện vào Tần Hạo từ khi còn là phôi thai, còn hình chiếu được cấy vào ngực hắn mỗi ngày để chuẩn bị cho việc cấy bản thể. Bất Lão Thiên Tôn không dám tự cấy cốt vì tuổi già và nguy cơ hình thần đều diệt, nên muốn khối cốt sống lại trong Tần Hạo rồi nhận lại cốt văn từ hắn. Khối cốt vẫn duy trì sinh cơ qua vô số năm và được suy đoán có thể là Trường Sinh cốt hoặc Tiên cốt, nhưng quá trình cấy ghép vẫn có thể khiến Tần Hạo mất mạng. Cuối chương, Tần Di Ninh kể rằng Sinh linh Bất Diệt đã đại náo thượng giới, giết hai kẻ thù dù trọng thương rồi bị ép trốn vào khu vực thần bí, đồng thời cảnh báo Thạch Hạo không nên trở thành kẻ địch chung của các thế lực khi lên thượng giới."},{"chuong":558,"tieuDe":"Tiểu Niết Bàn Đan","tomTat":"Thạch Tử Lăng và Tần Di Ninh vội trở lại Huyền vực để bảo vệ Tần Hạo trong quá trình cấy Tiên cốt, đồng thời hẹn sau khi lên thượng giới sẽ tìm Thạch Hạo đoàn tụ. Trước khi rời hạ giới, Thạch Hạo huy động chư hầu dâng linh dược và dùng dược đỉnh bạc cấp Thần để luyện hai lò Tiểu Niết Bàn đan, tổng cộng thu được sáu viên. Nó truyền đan phương và kỹ thuật điều khiển hỏa hầu cho Thanh Phong, giữ một viên cho mình, trao một viên cho Thanh Phong và giúp Chiến Vương dùng một viên đột phá lên Tôn giả. Ba viên còn lại được giao cho Chiến Vương cùng Bằng Cửu, người cũng vừa bước vào Tôn giả, lựa chọn những người thích hợp để tăng cường sức mạnh bảo vệ Thạch quốc. Sau đó Thạch Hạo tới Hỏa quốc nhưng không can thiệp cuộc tranh ngôi, rồi tìm khắp Hoang vực nhằm báo thù Thôn Thiên Tước, Cùng Kỳ và Tỳ Hưu mà không thu được kết quả. Cuối cùng, nó trở lại Hư Thần giới, khiến Vực Sứ kinh hãi bằng sức mạnh vượt cực hạn và dự định phá thêm kỷ lục để lấy hai mảnh đồng thau còn thiếu, qua đó tập hợp đủ mười mảnh đổi lấy một bảo thuật cái thế."},{"chuong":559,"tieuDe":"Điểu Gia Và Tinh Bích Đại Gia","tomTat":"Vực Sứ nhận ra Thạch Hạo là người từng bị Hư Thần giới trục xuất nhưng không giải đáp vấn đề hắn đang truy tìm, chỉ bảo hắn tự tìm câu trả lời rồi biến mất. Tại Sơ Thủy địa, Điểu gia và Tinh Bích đại gia mượn danh tiếng của Thạch Hạo để bán sổ tay, cốt thư cùng bí pháp thí luyện giả cho những người trẻ mới đến. Thạch Hạo trà trộn vào đám đông để tìm hiểu về sách quý đồng thau, khiến hai lão định bỏ chạy khi nhận ra chính chủ. Qua lời kể của một ông lão, hắn biết Điểu gia và Tinh Bích đại gia đã tồn tại từ thời tổ phụ người này còn trẻ mà dung mạo vẫn không đổi. Biết Thạch Hạo đã có tám khối sách quý đồng thau, Điểu gia chỉ cho hắn cách thu thập phần còn lại bằng việc liên tiếp phá kỷ lục. Thạch Hạo lập tức tiến lên qua nhiều khu vực của Hư Thần giới, phá hàng chục kỷ lục, trong đó có thành tựu sinh mệnh của Yêu Nguyệt và thành tựu thân thể của Lục Đạo, nhưng không vượt được Ngự Hỏa thuật của Hỏa Vân Tiên. Khi hai lão bám theo hắn, mỗi kỷ lục mới dường như đều tẩm bổ họ, khiến ánh mắt ngày càng thâm thúy và khí thế kinh khủng dần bùng lên."},{"chuong":560,"tieuDe":"Đường Đăng Thiên","tomTat":"Trong lúc Thạch Hạo tiếp tục phá kỷ lục tại Hư Thần giới, sức mạnh và ký ức bị phủ bụi của Điểu gia cùng Tinh Bích đại gia dần khôi phục, dù cả hai vẫn chưa nhớ ra thân phận thật. Họ xác nhận mình là người thật và tiết lộ rằng hai khối đồng thau cuối chỉ xuất hiện khi Thạch Hạo vượt qua một con đường đặc biệt rồi đánh bại toàn bộ đối thủ. Tinh Bích đại gia mở hai cánh cửa đồng thau khổng lồ, để lộ thiên lộ lơ lửng giữa hư không, nơi người bước sai sẽ rơi xuống vực sâu và bị sát khí cắt nát. Thạch Hạo một mình chịu áp lực tăng dần, đi suốt ba ngày ba đêm mới tới đài đồng thau ở cuối đường. Nó đánh tan tầng sức mạnh vô hình bảo vệ lối vào rồi bước lên đài cao vừa giống tế đàn vừa giống võ đài. Khi sương mù tan đi, Thạch Hạo nhìn thấy một cô gái áo vàng che mặt đã đứng chờ ở đó; nàng tự xưng là thiên tiên, còn nó đáp lại bằng thân phận Nhân Hoàng."},{"chuong":561,"tieuDe":"Phượng Vũ","tomTat":"Thạch Hạo nhìn thấy hình chiếu của một thế giới hùng vĩ trên con đường hướng lên trên rồi gặp Phượng Vũ, cô gái áo vàng thuộc Tiên viện tới đài Đồng Tức kính viếng tiền nhân. Phượng Vũ tưởng hắn là hậu đại đại hung từ phía dưới đi lên và muốn bắt làm tọa kỵ, dẫn đến cuộc đấu khẩu rồi giao chiến trên đàn Đồng Tước. Nàng dùng Súc Địa Thành Thốn, Thần Tiễn thuật và Thiên tiên quang, còn Thạch Hạo ứng chiến bằng thân pháp Côn Bằng, Bảo Thuật của Toan Nghê cùng lực Thái Âm và Thái Dương. Sau hàng loạt va chạm ngang ngửa, Thạch Hạo nhận ra sức mạnh cận chiến của Phượng Vũ được Thiên tiên quang gia trì. Khi nàng chuẩn bị vận dụng cấm thuật và thiên phú thần thuật, hắn phát động sức mạnh Chí Tôn cốt để áp chế rồi khiến nàng teo nhỏ thành bé gái tám, chín tuổi. Phượng Vũ không chịu nhận thua và bỏ chạy khỏi đàn Đồng Tước, còn Thạch Hạo truy đuổi nàng để đòi thực hiện lời hứa làm tọa kỵ. Hai người tiến tới hai cánh cửa vàng cao hơn núi, nơi một người đá đã nhen nhóm Thần hỏa đang ngồi trấn thủ."},{"chuong":562,"tieuDe":"Đàn Đồng Tước","tomTat":"Thạch Hạo bắt Phượng Vũ đang chạy trốn, đưa nàng trở lại đàn Đồng Tước và phong ấn, bất chấp lời khiêu chiến rằng nàng có thể hạ nó trong ba chiêu. Phượng Vũ công khai danh tính rồi dùng bí pháp Binh giải, hóa thành mưa ánh sáng để trở về hiện thực và để lại một thanh tiểu kiếm trong tay đối phương. Thạch Hạo triển khai Pháp môn Côn Bằng truy kích nhưng không kịp ngăn nàng tiến vào cửa Hoàng kim. Qua lời những tu sĩ trẻ phía sau cửa, nó biết Phượng Vũ là thiên tài Tiên viện đã tu thành Thiên tiên quang và từng lập nhiều chiến tích trước thiên kiêu các tộc. Theo chỉ dẫn của Điểu gia, Thạch Hạo phải vượt cửa Hoàng kim để đoạt Sách quý đồng thau, nhưng một Người đá trấn thủ mang thần hỏa đang ngồi gần đó và thiêu hủy sợi tóc chứa thần lực mà nó dùng để dò xét. Một nhóm cường giả trẻ tới đàn Đồng Tước, nhận ra Thạch Hạo là hậu đại đại hung hiếm hoi bò lên từ phía dưới và định lập tức truyền tin. Tại học viện Thiên Tiên, Phượng Vũ tỉnh lại với nguyên khí dường như bị tổn thương, vẫn tức giận vì bị Thạch Hạo trêu chọc và tự hỏi liệu sau này nó có tới Tiên viện hay không."},{"chuong":563,"tieuDe":"Đại Hung Hạo Thiên","tomTat":"Thạch Hạo đuổi kịp các tu sĩ định bỏ chạy trên đàn Đồng Tước, dùng tiểu kiếm chém đứt Thiên La Tán rồi lấy bảo thuật Toan Nghê mạnh hơn khắc chế người thi triển cùng thuật. Hắn tiếp tục phá Nam Ly thần hỏa, bắt và phong ấn tám người để ngăn họ binh giải, sau đó dùng Trấn Hồn Tháp buộc họ khai báo về Linh giới, cửa Hoàng kim và người đá trấn thủ. Qua lời tù binh, Thạch Hạo biết Phượng Vũ được xưng bất bại tại Thiên Tiên châu và có thể thuộc hàng sơ đại, từ đó càng mong sớm bước lên sân khấu thượng giới. Khi đội Linh Viên của Hỏa Vân Động mang trận kỳ tới vây bắt, hắn tự xưng Hạo Thiên rồi phối hợp pháp môn Côn Bằng với kiếm ý cây cỏ để phá tan đại trận. Phần lớn đối thủ tự hủy để thoát giới, lão Viên dùng quyển trục xuyên không chạy trốn và năm Linh Viên còn lại bị bắt. Dù Thạch Hạo không giết ai, tin tức truyền tới Thiên Tiên châu lại bị thổi phồng thành chuyện đại hung Hạo Thiên suýt giết sạch và ăn thịt hơn trăm cường giả, khiến nhiều tu sĩ cùng các thiên kiêu sơ đại bắt đầu chú ý."},{"chuong":564,"tieuDe":"Cường Giả Như Rừng","tomTat":"Tại Học viện Thiên Tiên, Phượng Vũ định dùng thánh dược khôi phục nguyên khí rồi trở lại đàn Đồng Tước, bởi nàng không phục thất bại trước Hạo Thiên và muốn thi triển thần thuật thiên phú. Ở đàn Đồng Tước, một đội ngũ tộc Bạch Ngân dùng Đóa hoa Bạch ngân phong tỏa hư không, nhưng Thạch Hạo cưỡng ép phá áp chế, đánh tan đội hình và bắt giữ ba người. Khi hơn trăm hậu duệ Sơn thần của tộc Cự Thạch kéo tới, Đả Thần Thạch cắn phá thân đá và hút tinh hoa khiến họ đại thương nguyên khí. Chân Lôn của Linh tộc sau đó giao chiến hơn trăm hiệp với Thạch Hạo, dùng mắt dọc năm màu và chiến mâu ngưng huyết làm bàn tay đối phương bị thương, nhưng cuối cùng bị cánh Côn Bằng đánh trọng thương. Biết Chân Cổ mạnh hơn em trai rất xa, Thạch Hạo nhờ Chân Lôn chuyển lời muốn lĩnh giáo Chí Tôn mâu cộng sinh với tay trái của vị sơ đại này. Ngay sau khi Chân Lôn rời đi, một sơ đại bí ẩn xuất hiện qua cửa Hoàng kim trong vầng mặt trời vàng, khiến đám đông quỳ xuống rồi trực tiếp trấn áp Thạch Hạo."},{"chuong":565,"tieuDe":"Hỏa Kim Đằng Nhất","tomTat":"Một chàng trai tóc tím ngồi trong vầng mặt trời vàng giáng xuống đàn Đồng Tước và dùng khí thế trấn áp Thạch Hạo, nhưng lần va chạm đầu tiên giữa hai người chưa phân thắng bại. Người quan chiến nhận ra hắn là Đằng Nhất, sơ đại trẻ tuổi bất bại của tộc Hỏa Kim, từng quét ngang các cường giả tại mười vạn Thánh sơn và còn giữ địa vị người Hộ đạo. Đằng Nhất công khai ý định hàng phục Thạch Hạo rồi bắt nó về bảo vệ sơn môn. Hắn thi triển thần ấn nhật nguyệt, diễn hóa đại nhật, thần nguyệt và vô số sao trời, song Thạch Hạo dùng dấu ấn Côn Ngư, chim bằng cùng hai khí Âm Dương phá tan dị tượng. Đằng Nhất tiếp tục tái hiện Hỏa Kim Bảo Bình Ấn, tuyệt học thời Thái Cổ từng dần thất truyền của tộc Hỏa Kim. Bảo bình đỏ phun ra thần hỏa Nam Ly, tinh hỏa thái dương và niết bàn sinh hỏa với các hình thái hỏa thước, Kim Ô và Chân Hoàng. Trước sức ép chết người ấy, Thạch Hạo vận chuyển pháp môn Côn Bằng và toàn lực điều khiển hai khí Âm Dương, còn trận chiến vẫn chưa ngã ngũ."},{"chuong":566,"tieuDe":"Ai Dám Chiến Một Trận","tomTat":"Đằng Nhất triển khai Hỏa Kim Bảo Bình Ấn, diễn hóa nhiều loại chim thần, thiên hỏa, Nghiệp hỏa và biển kiếm khí để vây giết Thạch Hạo. Thạch Hạo dùng bảo thuật Côn Bằng, thần y Âm Dương và Âm Dương Nghịch Chuyển lần lượt phá giải các đợt công kích, trong khi cả hai đều chịu thương tích. Khi Thạch Hạo muốn so tài Chí Tôn thuật, Đằng Nhất thừa nhận cấm pháp giáng lâm đã hết thời hạn nên không thể tiếp tục chiến đấu bằng năng lực thiên phú. Thạch Hạo không để đối thủ thong dong rút lui mà kích phát ký hiệu từ Chí Tôn cốt, nghiền nát hóa thân Đằng Nhất thành tro. Chiến thắng này kết thành nhân quả cho một cuộc quyết đấu sinh tử giữa bản thể hai người trong tương lai. Sau đó, Thạch Hạo công khai khiêu chiến các sơ đại và thiên kiêu Chí tôn khiến đám đông bỏ chạy về cửa Hoàng kim. Nhận thấy người đá canh cửa không phản ứng nếu không bị công kích, hắn mạo hiểm vượt qua và chính thức tiến vào Linh giới."},{"chuong":567,"tieuDe":"Hành Trình Ở Linh Giới","tomTat":"Thạch Hạo bước qua cửa Hoàng kim vào Linh giới, quan sát vùng thần thổ liên hệ với thượng giới và tìm người hỏi về con đường đưa chân thân đi lên. Danh tiếng Hạo Thiên khiến các tu sĩ kinh hãi bỏ chạy, còn việc hắn truy đuổi để hỏi chuyện dẫn tới một dòng người kéo dài hơn năm trăm dặm và làm bùng phát thú triều. Một Tôn giả Tây Phương giáo mang bình bát tới hàng yêu phục ma nhưng bị Thạch Hạo dùng Thất Thập Nhị Biến hóa thành Côn Bằng đánh bại và nhốt vào chính bảo cụ của mình. Thanh Ca thuộc Liên tộc sau đó chặn đường, dùng kim liên và thần hỏa dẫn động đại thế thiên địa để trấn áp, luyện hóa Thạch Hạo. Thạch Hạo hóa ba đầu sáu tay điều khiển lôi điện, phá tan hoa sen, bắt giữ Thanh Ca và ngăn hắn tự binh giải. Sau khi đưa hai tù binh về Đàn Đồng Tước và hỏi được thông tin về các con đường lên thượng giới, Thạch Hạo thả họ rồi đi xuống thiên lộ để chuẩn bị cho chân thân lên đường. Khi hắn đã rời cửa Hoàng kim, phong ba tại Linh giới tiếp tục lan rộng và thu hút cả Chí cường giả lẫn sơ đại chân chính kéo tới."},{"chuong":568,"tieuDe":"Nuốt Ngàn Vạn Sinh Linh","tomTat":"Thạch Hạo rời Linh giới trước khi Thanh Tiên, Chân Cổ, Đằng Nhất và các cường giả thượng giới kịp đuổi tới, còn Điểu gia đóng cửa đồng thau để bảo vệ Hư Thần giới. Điểu gia và Tinh Bích đại gia tiếp tục đối diện bí ẩn về chân thân cùng ký ức bị che khuất, trong khi Thạch Hạo nhận khối sách đồng thau thứ chín. Trở lại Thạch quốc, nó thấy Thanh Phong chưa sẵn sàng kế vị nên triệu tập các Vương bàn chọn người khác, và Thạch Hằng được đề cử như một ứng viên sáng giá. Thạch Hạo tạm hoãn dùng Tiểu niết bàn đan, bế quan nghiên cứu Vạn Linh đồ và lĩnh hội thêm áo nghĩa của Chân giải. Hai cốt thư khẩn sau đó báo Thôn Thiên tước đã nuốt hàng chục triệu sinh linh tại biên giới phía Tây, khiến nó triệu tập Bóng Lông và Tiểu Hồng cùng lên đường. Tại vùng tuyệt địa vạn dặm, Thạch Hạo chứng kiến thành trì đổ nát và sinh linh biến mất rồi tới phủ Hỗn Thiên hầu tìm hiểu tình hình. Thạch Hằng lập tức lộ rõ phản ý, thừa nhận Thần thượng giới muốn Thạch Hạo chết và tuyên bố sẽ đoạt quyền cai trị Thạch quốc. Thạch Hạo nhận ra tin về Thôn Thiên tước là mồi nhử, đồng thời khẳng định địa vị Nhân Hoàng và tuyên bố ngay cả Thần thượng giới tới cũng sẽ bị tiêu diệt."},{"chuong":569,"tieuDe":"Mãng Thần","tomTat":"Tại phủ Hỗn Thiên hầu, Thạch Hằng công khai phản nghịch và thừa nhận đã dụ Thạch Hạo vào sát cục để giết hắn, đoạt Chí Tôn cốt rồi kế thừa ngôi vua. Lão bộc của hắn dùng tia chớp luyện từ sinh hồn tấn công nhưng bị Thạch Hạo phá tan công kích và đánh nát nửa thân. Khi đại điện cùng tượng thần bay lên trời, một con Phi mãng có cánh tím xuất hiện và thừa nhận đã tàn sát hai vạn Nhân tộc để nhen nhóm Thần hỏa. Nó còn tuyên bố sẽ giết Thạch Hạo, lấy Chí Tôn cốt giao cho chủ nhân và ăn thân thể hắn. Thạch Hạo gọi Tiểu Hồng ra ứng chiến, khiến Phi mãng bị phá lửa Thần linh, đánh vỡ phù văn hộ thể và cắt đôi thân thể. Phi mãng trọng thương thu nhỏ rồi chạy về vai một Kim thân thượng giới vừa thức tỉnh từ tượng thần do phàm nhân nặn. Trước chỗ dựa thật sự của phe phản nghịch, Thạch Hạo phủ nhận đối phương xứng đáng là Thần, còn Tiểu Hồng tuyên bố sẽ ăn Phi mãng."},{"chuong":570,"tieuDe":"Thần Linh","tomTat":"Thạch Hạo đối chất với tượng thần mạ vàng và biết đối phương là một luồng ý chí của sát thủ Thiên quốc được đưa từ thượng giới xuống. Minh chủ, bá chủ Ma Quỳ viên và chủ nhân Thiên quốc đã trả giá lớn để mở khe hở hư không, còn Minh tộc cùng Ma Quỳ viên là hai thế lực muốn giết Thạch Hạo nhất. Tượng thần áp chế Tiểu Hồng bằng phù văn Thần linh và Thế giới trong lòng bàn tay, nhưng Bóng Lông bất ngờ xuất hiện phá vỡ thần thông. Được trang bị pháp khí cùng giáp trụ Chân Thần từ bảo khố Thạch quốc, Tiểu Hồng và Bóng Lông đánh trọng thương tượng thần, giết phi mãng rồi phá hủy vật dẫn của luồng ý chí. Ở chiến trường khác, Thạch Hằng lấy Huyết Ma thước đã được sửa chữa hoàn chỉnh ra quyết chiến, khiến toàn thân trở nên đỏ máu và tà dị. Thạch Hạo mặc chiến y Bất diệt kim thân, hóa thành Côn Bằng phá hủy cung điện trong hư không và tiêu diệt lão hầu bên trong. Cuối cùng, Tiểu Hồng nhận ra Huyết Ma thước thực chất là một Ma thần có khả năng chạy thoát và yêu cầu dùng đại trận niêm phong."},{"chuong":571,"tieuDe":"Bình Loạn","tomTat":"Thạch Hạo dựng tế đàn và đại trận phong tỏa chiến trường, giao đấu với Thạch Hằng đang bị Huyết Ma thước khống chế. Bóng Lông hợp nhất lực Chu Yếm, Chân Long và Côn Bằng, phối hợp cùng Tiểu Hồng đánh tan cường giả Thiên quốc thành mưa ánh sáng. Ông lão áo xám lẻn vào cứu đồ đệ và triển khai huyết độn, nhưng bị Đả Thần Thạch chặn đường; kỳ thạch này đã tiến hóa thành phôi thô chí bảo nhân gian nhờ ăn thần liệu trong bảo khố. Bóng Lông và Tiểu Hồng tiếp tục dùng pháp khí Chân Thần đánh nát Huyết Ma thước rồi thiêu sạch bằng Thần hỏa, dập tắt nguy cơ Ma thần thoát ra. Ông lão áo xám dùng Nguyền rủa mâu chứa oán niệm của ngàn vạn sinh hồn, song Thạch Hạo hóa Côn Bằng phá hủy cốt mâu rồi truy sát và giết lão. Thạch Hằng bị phế sạch tu vi, thừa nhận dục vọng của bản thân và tự sát, đồng thời cảnh báo Thạch Hạo về Thiên quốc huyết tế. Sau khi bình định biên giới phía Tây, Thạch Hạo trở về hoàng cung, triệu Chiến Vương, Minh vương và Bằng Cửu rồi tuyên bố thoái vị."},{"chuong":572,"tieuDe":"Chiến Thiên Ý","tomTat":"Thạch Hạo đặt Nhân Hoàng ấn lại trên Long án thư, công khai thoái vị và nhờ Chiến Vương, Bằng Cửu cùng các Tôn giả bảo vệ Thạch quốc, phụ tá Thanh Phong hoặc chọn người kế vị khác nếu cần. Nó tới Tam Sinh Sơn công khai bế quan, chủ động lấy mình làm mục tiêu để những kẻ thượng giới muốn trả thù không gây họa cho quốc gia và thân hữu. Trong hơn một tháng, Thạch Hạo quan sát Vạn Linh đồ, suy ngẫm lời Liễu Thần và thử khắc phù văn Luân Hồi của Chí Tôn cốt lên toàn bộ huyết nhục, xương cốt, nhưng các phù văn đều bị bảo cốt hút trở lại. Cùng lúc đó tại thượng giới, nhiều đại năng quyết định chiến thiên ý, chấp nhận nguy cơ bị đại đạo phản phệ để đưa cường giả đã nhen nhóm Thần hỏa xuống hạ giới tìm thiên Siêu thoát và các tạo hóa. Minh thổ cung cấp khung xương Hư Không thú gần cấp Chí Tôn để hỗ trợ phá giới, đồng thời đặt điều kiện phải giết Thạch Hạo. Tại Hồng vực, tế đàn đen đã được dựng trong đầm lầy và những kẻ thuộc nhiều đạo thống dùng ống tay áo, hồ lô máu cùng túi càn khôn thu bắt vô số sinh linh từ một Cổ quốc, quốc thổ Mộc tộc và các khu vực khác. Biến cố huyết tế làm cả hạ giới lẫn thượng giới rung chuyển và được dự báo sẽ ảnh hưởng đến cục diện trong vạn năm sau."},{"chuong":573,"tieuDe":"Huyết Tế Thiên Địa","tomTat":"Trong một cổ điện ở thượng giới, hai nhân vật bí ẩn nhìn thấy điềm báo thiên địa nhuốm máu, huyết nguyệt xuất hiện và khe hở hư không sắp mở. Sau hai tháng bế quan tại Tam Sinh sơn, Thạch Hạo tỉnh khỏi ngộ đạo vì bất an, xuống trấn nhỏ và nhớ tới Thạch thôn cùng cha mẹ. Qua lúc vui chơi với đám trẻ, nó xác định vẫn sẽ tiến lên thượng giới nhưng không muốn trở thành một vị Thần lạnh lùng, xa cách hồng trần. Tại Hồng vực, những người chủ trì tế đàn đen hiến tế hơn ngàn vạn người cùng vô số sinh linh, dùng máu, hồn lực và tinh hoa sinh mệnh để mở đường giữa hai giới. Trong cổ điện, Minh chủ đưa khung xương và da Hư không thú vào nghi thức, còn các giáo chủ đặt mười mấy sinh linh đã nhen nhóm Thần hỏa vào Lò luyện hư không. Thiên ý giáng thiên đao và tia chớp hỗn độn xuống ngăn cản, làm hư hại cung điện và khiến những người thi pháp chịu phản phệ. Cuối cùng, các giáo chủ vẫn mở được khe giới, để Hư không thú mang theo nhóm cường giả tiến xuống hạ giới."},{"chuong":574,"tieuDe":"Bảy Thần Hạ Giới","tomTat":"Hồng vực xuất hiện dị tượng Trời khóc sau khi vô số bộ tộc, thành trì và dân cư đột ngột biến mất để phục vụ một cuộc huyết tế. Từ thượng giới, các tồn tại trong một cung điện cổ hợp lực chống thiên ý, chịu phản phệ để giúp một Hư Không Thú mang Lò Luyện Hư Không vượt giới. Hư Không Thú bị thiên phạt hủy diệt hoàn toàn, còn chiếc lò rơi trúng tế đàn huyết tế, phá hủy tế đàn cùng vô số sinh hồn và bản thân cũng gần như mất hết uy lực. Bảy sinh linh đã nhen nhóm Thần hỏa sống sót phá lò thoát ra, nhanh chóng thích ứng với pháp tắc không hoàn chỉnh của hạ giới. Họ chia nhau thần thi của những người vượt giới đã chết, rồi khung xương vàng truyền lại mệnh lệnh của Minh chủ rằng phải ưu tiên giết Thạch Hạo. Nhóm quyết định tạm thời phân tán để tìm đạo thống, binh khí và giải quyết việc riêng trước khi tái hợp, đồng thời bắt các Tôn giả ở xa dẫn đường. Tin tức về huyết tế Hồng vực và việc có người chống đại đạo mở thông đạo từ thượng giới nhanh chóng lan khắp tám vực, khiến các tộc đều chấn động và bất an."},{"chuong":575,"tieuDe":"Ván Cờ Tất Chết","tomTat":"Dị tượng Thiên khóc xuất hiện sau khi hàng chục triệu đến hơn trăm triệu sinh linh bị huyết tế để mở đường cho bảy vị Thần vượt xuống hạ giới. Tại Tam Sinh sơn, Thạch Hạo phẫn nộ trước thảm họa và bác bỏ lời khuyên ẩn nhẫn của Chiến Vương, Bằng Cửu cùng các thống lĩnh vì không muốn người vô tội bị liên lụy. Thạch Tử Lăng và Tần Di Ninh vội tới khuyên con tránh nạn, đồng thời báo rằng Tần Hạo đã tỉnh lại sau khi cấy thành công Chí Tôn cốt và dùng thần đan thượng giới để tái tạo thân thể. Không dám trở về Thạch thôn vì sợ dẫn tai họa về quê, Thạch Hạo tới một trấn nhỏ, dẫn những đứa trẻ nghèo đi mua thức ăn để ôn lại ký ức tuổi thơ. Một hạc giấy từ hoàng cung sau đó báo rằng các vị Thần đã giáng lâm hoàng đô Thạch quốc, gọi đích danh Thạch Hạo và đe dọa tàn sát nơi ấy nếu nó không tới chịu phạt. Thạch Hạo chia tay cha mẹ, lập tức lên đường và chấp nhận bước vào ván cờ gần như chắc chắn phải chết."},{"chuong":576,"tieuDe":"Ngông Cuồng","tomTat":"Biết bảy Thần hạ giới đang săn mình và hoàng cung gần như đã trở thành tử cục, Thạch Hạo vẫn một mình trở lại Thạch đô, đồng thời để Đả Thần Thạch, Hoàng điệp, Bóng Lông và Tiểu Hồng tránh xa nguy hiểm. Trong hoàng cung tan hoang, các thị vệ trung thành khuyên nó rời đi nhưng nó vẫn tiến vào trung ương thiên cung. Tại đây, Dương Ly của học viện Âm Dương, một vị Thần khung xương vàng từ Minh thổ và Xuyên sơn giáp màu bạc của Thú hải đang bắt giữ Thanh Phong, Chiến Vương, Bằng Cửu cùng Minh vương. Ba Thần hành hạ những người bị bắt nhưng chưa giết họ vì muốn dùng các Tôn giả làm người phát ngôn để thao túng Thạch quốc và tìm kiếm tạo hóa. Thạch Hạo kiềm chế lửa giận cho tới khi xác nhận các con tin chưa gặp nguy hiểm tức thời, sau đó mặc chiến y Bất diệt kim thân khiến ba đối thủ đồng loạt nổi lòng tham. Nó dịch chuyển lên trời cao phía trên hoàng cung và công khai gọi ba ngụy thần tới nhận chết."},{"chuong":577,"tieuDe":"Đường Cùng","tomTat":"Ba cường giả đã nhen Thần hỏa nhận ra chiến y của Thạch Hạo là Bất diệt kim thân hư hại và cùng truy đuổi hắn, dù mỗi kẻ đều muốn độc chiếm cổ khí này. Thạch Hạo giải thể quyển sách chữ Giết để công kích hồn phách Xuyên sơn giáp màu bạc, nhưng chỉ khiến mi tâm đối phương chảy máu. Hắn tiếp tục dẫn địch vào sát trận vùng núi rồi dùng hoa sen thần hỏa đánh Dương Ly, song cả hai phương án đều không thể giết được Thần. Thạch Hạo phối hợp Súc địa phù với pháp môn Côn Bằng, dùng hạt Ma quỳ bổ sung thần năng và chạy trốn suốt một ngày một đêm. Sau khi truyền tống tới Bắc Hải, hắn thử cộng hưởng với sào huyệt Côn Bằng và mong Thiên Hoang đại kích xuất hiện, nhưng không nhận được bất kỳ đáp lại nào. Bị dư âm bảo thuật đánh trọng thương và dồn tới đường cùng, Thạch Hạo quyết định dẫn ba kẻ truy sát vào một tử địa mà bản thân từng chỉ may mắn mới sống sót rời khỏi."},{"chuong":578,"tieuDe":"Dọa Phá Thần Đảm","tomTat":"Thạch Hạo bị ba cường giả Thần hỏa đuổi kịp và đánh trọng thương, nhưng vẫn tìm được tế đàn truyền tống trong một tòa thành phía Bắc để tiếp tục đào thoát. Nó thi triển Bảy mươi hai biến hóa thành Côn Bằng, dùng Súc địa phù gia tốc và nuốt hạt Ma Quỳ để cầm máu, phục hồi tinh khí thần. Thạch Hạo chủ động dẫn Dương Ly, Xuyên sơn giáp và cường giả Minh thổ vào Tây Lăng giới, nơi có vô số anh linh hung thú cấp Thiên gần thực thể hóa. Ba kẻ truy sát nhận ra vùng đất này đang bước đầu hình thành thành một giới và có thể thai nghén chí bảo, còn cường giả Minh thổ cho rằng nơi đây có khả năng phát triển thành Minh giới. Tại một cổ đàn màu đen, họ bị xương tay vàng, xương sọ thủy tinh và tròng mắt dính máu thu hút nên tạm gác việc bắt Thạch Hạo. Lợi dụng việc đối phương không dám vận dụng thần lực gần tế đàn, Thạch Hạo khiêu khích rồi đạp mạnh làm cổ đàn chấn động. Ba cường giả hoảng sợ tháo chạy, nhưng tròng mắt dính máu đã chuyển động, khóa chặt họ và dẫn phát một sức mạnh kinh khủng muốn giam cầm cả nhóm."},{"chuong":579,"tieuDe":"Bị Tiêu Diệt","tomTat":"Tế đàn trong Tây Lăng giới hình thành tràng vực hủy diệt, phát ra gợn sóng đen khóa chặt Xuyên sơn giáp, Dương Ly và cường giả Minh thổ dù cả ba đều đã nhen nhóm Thần hỏa. Không còn cách tự bảo vệ, Thạch Hạo trốn vào tiểu thế giới của Hộp báu đồng thau, cầm Vạn Linh đồ và chấp nhận đánh cược mạng sống. Xương tay màu vàng bay khỏi tế đàn, nghiền nát thân thể các cường giả rồi đánh thủng và xé nát Lò luyện hư không mà họ dùng làm nơi trú ẩn. Xương sọ thủy tinh tiếp tục hút gần cạn huyết nhục, bản nguyên và tinh hoa linh hồn, khiến cả ba trở thành những tàn thể không thể sống sót. Khi hai tế phẩm xương tiến gần Hộp báu đồng thau, Vạn Linh đồ phát sáng với phù văn vạn linh và khí hỗn độn, khiến chúng dừng lại rồi rút về tế đàn. Thạch Hạo mang ba tàn thể ra khỏi Tây Lăng giới, tìm được một số tin tức trọng yếu trong biển ý thức đã tan nát, lên án tội ác huyết tế hạ giới của họ rồi đá ba đầu lâu lên không trung và tiêu diệt hoàn toàn."},{"chuong":580,"tieuDe":"Buồn Vui","tomTat":"Từ ký ức còn sót lại của ba Thần đã chết, Thạch Hạo biết lão già Tiên điện và cường giả Tây Phương giáo là hai kẻ mạnh nhất trong số những đối thủ còn lại, khiến nó chưa tìm được cách phá tử cục. Trên đường về Thạch đô, nó gặp Vũ Tử Mạch và khiến thiên phú Thông linh của nàng bị phản phệ khi chỉ nhìn thấy tương lai hỗn độn cùng quá khứ hư vô. Tại hoàng cung, Thạch Hạo xác nhận với Bằng Cửu, Chiến vương và Minh Vương rằng ba Thần truy sát mình đều đã chết, rồi biết Thanh Phong từng trở về Thạch thôn cầu viện Bóng Lông và Tiểu Hồng. Những dấu vết thảm khốc tại chiến trường khiến nó ngộ nhận hai người bạn đã tử trận, nhưng khi về thôn mới phát hiện cả hai vẫn sống và cỗ quan tài thực ra được chuẩn bị cho chính mình. Bóng Lông bị mất nửa thân dưới, còn Tiểu Hồng bị xé nát đôi cánh và nứt Phù cốt nguyên thủy, nên Thạch Hạo trao cho mỗi người một giọt Hoàng kim dịch để chữa thương. Hai cường giả kể rằng họ đã mở phong ấn tổ khí Thạch thôn và nhờ Hắc đỉnh che chắn, phun đan hỏa thiêu chết Thần Tây Phương giáo. Sau trận chiến, lớp vỏ đen của Hắc đỉnh bong ra, để lộ cốt đỉnh trắng như ngọc rồi biến mất, trong khi một Thần khác đang phá hoại phế tích Bổ Thiên các và dò tìm Thánh viện thượng cổ."},{"chuong":581,"tieuDe":"Chiến Y Niết Bàn","tomTat":"Sau khi cốt đỉnh trắng của Thạch tộc biến mất, Thạch Hạo quyết định chủ động nghênh chiến để người thân và Thạch quốc không bị ba vị Thần còn lại trút giận. Nó nung chảy Hoàng Văn Thạch cùng một số vật liệu khác rồi dung nhập vào chiến y Bất diệt kim thân, khiến món giáp rạn nứt và vỡ thành nhiều mảnh. Dị tượng Phượng hoàng sau đó xuất hiện, giúp chiến y tái ngưng tụ, hoàn thành niết bàn và đạt sức phòng hộ đủ đối kháng cường giả đã nhen nhóm Thần hỏa. Bóng Lông và Tiểu Hồng chỉ dẫn Thạch Hạo khắc thêm phù văn che giấu khí tức thần thánh, còn Tiểu niết bàn đan được giữ làm phương án đột phá khẩn cấp lên cảnh giới Tôn giả. Trong lúc đó, một vị Thần đơn độc tàn phá khu di tích Bổ Thiên các và sát hại nhiều phàm nhân để tìm Thánh viện thượng cổ ẩn trong hư không. Thạch Hạo tới di tích sau khi hoàn tất chuẩn bị, khiến vị Thần mở mắt, phóng điện quang và lạnh lùng khóa chặt nó, mở đầu cuộc đối đầu trực diện."},{"chuong":582,"tieuDe":"Thủy Tổ Tái Hiện","tomTat":"Tại di tích Bổ Thiên các, Thạch Hạo chạm trán Ngân Dực, một vị Thần cánh bạc của Thiên quốc có tốc độ và thực lực vượt những kẻ truy sát trước đó. Nó bí mật mặc chiến y Bất diệt kim thân, dùng Bảy mươi hai biến cùng Súc địa phù né tránh, nhưng Ngân Dực nhanh chóng nhìn thấu kế dẫn địch vào Tây Lăng giới. Sau khi ám sát hụt, Ngân Dực giết phàm nhân và đe dọa san bằng Bổ Thiên các rồi tàn sát Thạch quốc, buộc Thạch Hạo phải ở lại quyết chiến. Qua lời hắn, Thạch Hạo biết người khai sáng Bổ Thiên các từng đối đầu với một cường giả siêu cấp của Thiên quốc và cả hai đều chết. Khi Thạch Hạo rút kiếm gãy nghênh chiến, binh khí bất ngờ bùng phát uy thế và giải phóng chấp niệm tỉnh táo của Quỷ gia. Quỷ gia cho biết ân oán với Thiên quốc vẫn chưa kết thúc và tiếc nuối vì người lão thực sự chờ đợi chưa xuất hiện. Lão tiếp nhận kiếm gãy, phá tan phù văn cùng sát kiếm của Ngân Dực, đánh nổ một cánh tay rồi chém đứt hai chân hắn khi hắn định ẩn vào hư không bỏ chạy."},{"chuong":583,"tieuDe":"Quỷ Gia","tomTat":"Ngân Dực thiêu đốt tinh huyết và dùng tế đàn đỏ triệu hồi các Thần ma huyết sắc, nhưng Quỷ gia lấy kiếm gãy quét sạch tất cả rồi phá hủy tế đàn và giết hắn đến hình thần đều diệt. Quỷ gia tiết lộ mình từng bị một cô gái Thiên quốc cùng đồng bọn ám sát, còn hình thái hiện tại chỉ là chấp niệm mô phỏng Sát kiếm Thiên quốc để phong giữ tàn hồn. Biết thần đằng Hồ lô đã nảy mầm lần nữa, lão từ chối gặp lại, trao kiếm gãy cho Thạch Hạo và gửi gắm tâm nguyện liên quan tới Thiên quốc trước khi vĩnh viễn tan biến. Sau đó, một người đàn ông áo đen của Ma Quỳ viên xuất hiện, thừa nhận đã quan sát Ngân Dực chết và cho biết trong bảy vị Thần hạ giới chỉ còn hai người sống sót. Hắn phụng mệnh chủ nhân bộ tộc truy sát Thạch Hạo để báo thù cho đệ tử đã chết. Thạch Hạo tiến vào cảnh giới Tôn giả, hóa thành Côn Bằng hình người để chuyển hóa dược lực còn sót, rồi kích hoạt chiến y Bất diệt kim thân đánh tan công kích và làm bàn tay đối phương chảy máu."},{"chuong":584,"tieuDe":"Chuyện Sau Khi Giết Chết Thần","tomTat":"Được Bất diệt kim thân gia trì, Thạch Hạo dùng pháp môn Côn Bằng cùng nhiều binh khí áp đảo cường giả Ma Quỳ viên, sau đó kích hoạt bảo thuật Luân hồi khiến đối thủ già yếu và suy kiệt. Nó chặt đầu vị Thần rồi dùng kiếm gãy và lôi đình truy diệt thần hồn, buộc đối phương tự bạo toàn bộ thân thể cùng bản thể hoa hướng dương đen. Thạch Hạo thoát khỏi trung tâm vụ nổ nhưng vẫn bị đánh bay hơn trăm dặm và trọng thương, rồi dùng một hạt hoa hướng dương để bổ sung thần năng. Tin tiểu Thạch giết Thần nhanh chóng truyền khắp tám vực, khiến phần lớn thiên hạ vui mừng và chấn động. Trở về Thạch thôn, Thạch Hạo biết cha mẹ vừa đi tìm mình, chữa thương bằng linh dược và thả Nguyệt Thiền khỏi hộp báu đồng thau. Nó giao Bóng Lông và Tiểu Hồng nhiệm vụ đưa Nguyệt Thiền rời thôn nếu mình không trở lại, đồng thời chuyển thông tin về những nơi có đại tạo hóa cho Thanh Phong. Dù Bóng Lông cảnh báo vị Thần cuối cùng của Tiên Điện không thể chiến thắng, Thạch Hạo vẫn chưa từ bỏ khả năng nghênh chiến. Trong những ngày tiếp theo, nó cùng trẻ nhỏ vào núi vui đùa và trân trọng quãng bình yên hiếm hoi như thuở ấu thơ."},{"chuong":585,"tieuDe":"Tiên Diện","tomTat":"Trong khi ngoại giới chờ đợi cuộc đối đầu với vị Thần cuối cùng, Thạch Hạo đưa người Thạch thôn trở lại nơi cư trú cũ để ôn lại ký ức. Đại Bằng và Tiểu Thanh đào được một bộ thần hài tử kim dài trăm trượng, bên trong còn hơn mười viên Thần tinh pha tạp tử khí. Thạch Hạo mang toàn bộ thần hài về thôn, giao Đả Thần Thạch phối hợp với Bóng Lông và Tiểu Hồng tế luyện thành đại sát khí cho trận chiến sắp tới. Sau khi từ biệt dân làng, nó dùng tế đàn truyền tống trở về hoàng cung Thạch Quốc. Tại Thạch đô, lão giả Hoàng Vũ đã vượt qua phòng vệ hoàng cung, tìm Bằng Cửu hỏi tung tích Thạch Hạo rồi ở lại chờ đợi. Khi Thạch Hạo trở về, hai người cảm ứng và đối ẩm từ xa; Hoàng Vũ tự nhận đến từ Tiên điện và mời nó gia nhập. Lão còn tiết lộ Tiên điện là địch thủ của Cung điện Chí Tôn, nói truyền thừa này từng chiến bại tại thượng giới rồi xuống hạ giới và dò hỏi việc Thạch Hạo tự xưng là truyền nhân duy nhất."},{"chuong":586,"tieuDe":"Thần Mạnh Nhất","tomTat":"Hoàng Vũ dò xét quan hệ giữa Thạch Hạo và Cung điện Chí tôn, dùng lời mời gia nhập Tiên điện làm bước mở đầu trước khi đưa ra ba điều kiện khắc nghiệt. Lão đòi xem pháp môn Côn Bằng, kiểm tra Chí Tôn cốt và phong ấn Thạch Hạo một trăm năm ở cảnh giới Tôn giả, đổi lại sẽ giúp nó thống nhất tám vực và tìm vận may trong Cung điện Chí tôn. Thạch Hạo nhận ra mục tiêu thật sự của lão là Chí Tôn huyết nên kiên quyết từ chối, rồi rời Thạch đô để tránh khiến dân chúng bị liên lụy. Hoàng Vũ tiết lộ mình là người mạnh nhất trong bảy vị thần vượt giới còn sống và đã khảo sát Bổ Thiên các, Bắc Hải cùng vùng ngoài Tây Lăng giới để chuẩn bị đối phó nó. Để ép Thạch Hạo khuất phục, lão nuốt sống mấy trăm cư dân của một thị trấn và đe dọa sẽ tàn sát dân Thạch quốc, tìm đến cha mẹ, em trai cùng Chiến Vương nếu nó tránh chiến. Thạch Hạo phẫn nộ, nắm đại kích tuyên chiến nhưng vẫn tiếp tục dẫn đối phương vào vùng núi hoang vắng. Hoàng Vũ sau đó tiết lộ một đại nhân trẻ tuổi của Tiên điện đã sai lão giết Thạch Hạo vì không vui trước lời đồn liên quan đến Nguyệt Thiền, người đang được Bổ Thiên giáo kỳ vọng dùng để kết giao với Tiên điện."},{"chuong":587,"tieuDe":"Trận Chiến Cuối Cùng","tomTat":"Hoàng Vũ đề cao Tiên điện và đe dọa tàn sát thủ phủ Thạch quốc, buộc Thạch Hạo phải ngừng chạy trốn để bảo vệ cha mẹ, người thân cùng dân chúng. Thạch Hạo thức tỉnh thần kích trấn quốc nhưng đòn đánh bị đối phương phá tan, còn lực phản chấn từ cú búng vào lưỡi kích khiến bàn tay nó rách nát. Nó mặc chiến y Bất diệt kim thân, thiêu đốt tinh khí thần và dung hợp kiếm cỏ với lực lượng Côn Bằng, Toan Nghê thành kiếm ý mạnh nhất, song vẫn bị chênh lệch cảnh giới áp chế. Hoàng Vũ nhận ra kiếm ý bắt nguồn từ một quyển da thú chứa tiểu thế giới bí ẩn và nhắc tới bí thiên mang hai chữ “Lục đạo”. Sau đó, lão triển khai tốc độ, lông thần, công kích tinh thần và đôi cánh vàng của hung cầm Thái Cổ để truy sát, khiến Thạch Hạo phải liên tục né tránh và chống trả. Thạch Hạo dụ lão vào khu vực đã bố trí phù cốt màu tím rồi kích nổ đại sát khí, nhưng vụ nổ chỉ làm Hoàng Vũ rách đạo bào và chảy máu. Nhận thấy bẫy không đủ hạ đối thủ, Thạch Hạo dùng viên Trùng đồng nhìn xuyên vùng năng lượng hỗn loạn, áp sát và phát động Chí Tôn cốt trong cơ hội phản kích cuối cùng."},{"chuong":588,"tieuDe":"Vận Dụng Chí Tôn Cốt","tomTat":"Giữa tràng vực hỗn loạn sau vụ nổ, Thạch Hạo vận dụng sức mạnh Luân hồi từ Chí Tôn cốt để tập kích Hoàng Vũ, nhưng lão dùng một con rối hình người chịu đòn thay rồi áp sát phản kích. Tấm da thú dung hợp với ngực và khối cốt dung hợp với tay phải giúp Thạch Hạo hóa giải đòn hiểm, đồng thời khiến Hoàng Vũ bị thương khi đối chưởng. Hoàng Vũ hiện bản thể tiên hạc, thi triển Tiên hạc tung cánh để xuyên thủng phòng ngự và làm Thạch Hạo ho ra máu, trong khi việc duy trì nhiều thần khí khiến thần lực của nó suy giảm nhanh chóng. Chí Tôn cốt hồi phục kịp thời, cho phép người tí hon màu vàng trên cốt ly thể thành một thần thể mang hình dáng Thạch Hạo và vượt qua khoảng cách không gian để truy trúng đối thủ. Sức mạnh Luân hồi khiến Hoàng Vũ già nua cấp tốc, sau đó thần thể chém trọng thương vai và đá lão vào đầu nhưng chưa thể phá vỡ xương sọ. Cuối chương, chân thân Thạch Hạo cầm thần kích trấn quốc phối hợp với thần thể Chí Tôn cốt giáp công, đánh Hoàng Vũ ho ra máu và bay ngược về phía lưỡi kích, song kết quả cuối cùng vẫn chưa được xác nhận."},{"chuong":589,"tieuDe":"Tuyệt Cảnh","tomTat":"Phù văn Chí Tôn của Thạch Hạo không thể làm Hoàng Vũ suy yếu mà trái lại giúp lão luyện hóa hoàn toàn thần đan của Tiên điện, chữa lành thương thế và khôi phục chiến lực đỉnh cao. Hoàng Vũ dùng cánh tiên hạc, búa nhỏ hoàng kim, tia chớp và Thế giới trong lòng bàn tay truy sát, buộc Thạch Hạo phải vận dụng Bảo thuật Côn Bằng, hạt Ma quỳ cùng nhiều pháp khí Chân thần để cầm cự. Lần phát động Chí Tôn cốt tiếp theo lại khiến Hoàng Vũ trẻ lại, còn Thạch Hạo bị pháp tắc hoàng kim vây kín và phải huyết tế pháp khí để phá đường thoát. Thạch Hạo chạy vào tổ địa Hỏa quốc, vượt biển dung nham và dẫn đối phương tới diễn võ trường có khả năng áp chế cảnh giới. Tại đây nó đánh bại Chu Yếm và dùng kiếm gãy xuyên thủng mi tâm Hoàng Vũ, nhưng kẻ bị giết chỉ là một linh thân được phái vào thăm dò. Chân thân Hoàng Vũ phục kích bên ngoài, đe dọa giết Chiến Vương, Bằng Cửu, cha mẹ Thạch Hạo cùng những người tại Thạch quốc nếu nó tiếp tục bỏ chạy. Không chấp nhận chịu phong ấn và làm trâu bò một trăm năm, Thạch Hạo nâng kiếm quyết định quay lại tử chiến."},{"chuong":590,"tieuDe":"Kết Thúc","tomTat":"Hoàng Vũ từ chối buông tha Thạch Hạo, hóa thành tiên hạc vàng và vận dụng búa nhỏ hoàng kim, pháp tắc Hoàng kim cùng Hoàng Kim phiến để đánh nó trọng thương. Thạch Hạo rút khỏi Hỏa quốc sang Thạch quốc nhưng cố tình tránh Thạch thôn, không muốn Hoàng Vũ phát hiện quê hương và bao vây tịnh thổ. Khi tới Tam Sinh sơn, nó thiêu đốt mười Động thiên, lấy chính mình làm mồi để kéo Hoàng Vũ vào thế tế sống. Hoàng Vũ đáp trả bằng cách triệu hồi bóng mờ Tiên điện bằng đồng đã được một vị đại nhân truyền vào cơ thể, gần như dập tắt ngọn lửa hiến tế và khiến thân thể Thạch Hạo rạn nứt. Trong thế thập tử vô sinh, Thạch Hạo quyết kéo đối phương chết cùng rồi mở Chí Tôn cốt, khiến lồng ngực nổ tung và ánh sáng vô tận bao phủ chiến trường. Chương khép lại khi nó bình tĩnh gửi lời từ biệt tới Thạch thôn và cha mẹ, còn kết quả của đòn cuối cùng vẫn chưa được xác nhận."},{"chuong":591,"tieuDe":"Tiểu Thạch Chết Non","tomTat":"Bị Hoàng Vũ ép vào tuyệt lộ, Thạch Hạo chủ động làm nổ Chí Tôn cốt, giải phóng đạo và pháp tắc trời sinh để xuyên thủng bóng mờ Tiên điện bằng đồng. Hoàng Vũ thiêu đốt tinh khí thần và sức mạnh bản nguyên để chống đỡ nhưng vẫn bị những mảnh cốt phá hủy cả thân thể lẫn nguyên thần. Trước khi hoàn toàn hóa thành tro, lão kích hoạt tinh hoa nguyền rủa luyện từ gỉ Tiên điện nhằm triệt đường sống của Thạch Hạo. Vụ tự hủy khiến thân thể Thạch Hạo chia năm xẻ bảy, hộp sọ rạn nứt và nguyên thần gần tan biến, còn Chí Tôn cốt chỉ sót lại những mảnh tàn khuyết. Khi nó đang chờ chết và hồi tưởng hành trình đã qua, cành liễu do Liễu Thần lưu lại bất ngờ thức tỉnh, thu hồi xương thịt và tạm ghép cơ thể. Tuy nhiên, quy tắc Tiên điện đã hòa vào huyết nhục và phá hoại mạnh hơn sức phục hồi của cành liễu. Nhận ra mình chỉ được kéo dài mạng sống trong thời gian ngắn, Thạch Hạo quyết định tận dụng quãng thời gian còn lại."},{"chuong":592,"tieuDe":"Sinh Mệnh Còn Không Nhiều","tomTat":"Sau trận chiến với Hoàng Vũ, Thạch Hạo luyện hóa toàn bộ cành liễu do Liễu Thần lưu lại để nối xương và tái tạo huyết nhục, nhưng quy tắc phá hoại cùng phù nguyền rủa của Tiên điện vẫn tiếp tục ăn mòn cơ thể. Chí Tôn cốt của cậu đã vỡ nát và thiếu một phần ba, khiến sinh mệnh lẫn căn cơ đều đứng trước nguy cơ tan rã. Trở lại hoàng cung Thạch quốc, cậu xác nhận đã giết vị Thần cuối cùng, giao lại thần kích trấn quốc bị gãy cùng các pháp kiếm hư hại rồi dùng tế đàn rời đi. Không muốn cha mẹ biết mình sắp chết, Thạch Hạo quyết định tới Bất Lão sơn gặp Tần Hạo để giao phó việc chăm sóc họ. Tại sơn môn, một nhóm cường giả cùng Tôn giả Bất Lão sơn lợi dụng thương thế của cậu để uy hiếp và định trấn áp. Thạch Hạo cưỡng ép vận dụng Chí Tôn cốt làm đối phương già nua, bắt giữ Tôn giả nhưng phải trả giá bằng việc ngực chảy máu và thêm một mảnh cốt rơi xuống. Cuối cùng, cậu truyền âm gọi Tần Hạo ra gặp mặt."},{"chuong":593,"tieuDe":"Thiên Hạ Sôi Trào","tomTat":"Mang thương thế chí tử tới Bất Lão sơn, Thạch Hạo phong ấn một Tôn giả để ngăn những người xung quanh lợi dụng lúc nó suy yếu ra tay. Nó gặp riêng Tần Hạo, thừa nhận mình không còn sống được bao lâu và nhờ em trai chăm sóc cha mẹ, đồng thời dự định trở về gần Thạch thôn để âm thầm chờ chết. Tại Hắc Thạch thành, Thạch Hạo sửa xong tế đàn truyền tống nhưng bị Thạch Tử Lăng, Tần Di Ninh và Tần Hạo tìm thấy, rồi ngất đi trước mặt cha mẹ. Trong lúc nó được đưa về Bất Lão sơn cứu chữa, tin chiến tích tiêu diệt toàn bộ bảy vị Thần truyền khắp tám vực, đưa thanh danh tiểu Thạch lên đỉnh cao, nhưng tin nó sắp chết cũng khiến thiên hạ tiếc thương. Sau một ngày hai đêm hôn mê, Thạch Hạo tỉnh lại nhờ một giọt Hoàng Kim dịch của thần thụ Thái Dương tạm giữ hơi thở, song các dược sư vẫn không thể chữa khỏi. Cuối cùng, một lão dược sư đề xuất dùng khối Tiên cốt đã cấy thành công trong cơ thể Tần Hạo để cứu Thạch Hạo, khiến Tần Di Ninh kinh hãi đánh rơi chén thuốc."},{"chuong":594,"tieuDe":"Lựa Chọn Khó Khăn","tomTat":"Trương Trọng xác nhận y thuật và bí pháp phù văn thông thường không thể cứu Thạch Hạo, rồi đề xuất lấy Tiên cốt trong cơ thể Tần Hạo để đối kháng cốt văn nguyền rủa. Phương án này có sáu đến bảy phần khả năng cứu Thạch Hạo nhưng cũng có ba phần khả năng khiến Tần Hạo tử vong. Thạch Hạo kiên quyết từ chối đánh đổi tính mạng em trai, trong khi Tần Hạo lại chủ động chấp nhận nguy hiểm để cứu anh, khiến Thạch Tử Lăng và Tần Di Ninh không thể đưa ra quyết định. Ban đêm, Tần Lan lẻn vào định ám sát Thạch Hạo nhưng bị cậu cưỡng ép Chí Tôn cốt phản kích, rơi vào luân hồi và già hóa. Tần Lan tự phá mi tâm để chết và cắt đứt manh mối, còn những người Tần tộc kéo tới lập tức quy tội cho Thạch Hạo. Thạch Tử Lăng nổi giận đuổi họ khỏi phòng, còn Thạch Hạo xin được trở về Thạch quốc. Hai vợ chồng cuối cùng nhận ra vụ ám sát nhằm ngăn họ lấy Tiên cốt của Tần Hạo để cứu con trưởng."},{"chuong":595,"tieuDe":"Các Vương","tomTat":"Các lão nhân Tần tộc đổ lỗi cho Thạch Hạo, nhưng Thạch Tử Lăng nhận ra con trai vừa bị mưu hại nên đuổi họ đi và triệu chiến mâu chuẩn bị giao chiến. Khi Thạch Hạo tiếp tục hôn mê và suy kiệt, Thạch Tử Lăng muốn dùng Tiên cốt của Tần Hạo để cứu trưởng tử, Tần Di Ninh phản đối hy sinh con thứ, còn Tần Hạo chủ động đồng ý hiến cốt cứu anh. Chiến vương, Minh vương và Bằng Cửu dẫn nhiều vương hầu Thạch quốc tới Bất Lão sơn, mang theo đan dược cùng thánh dược để duy trì sinh mệnh cho Nhân Hoàng. Trong lúc chuẩn bị hòa tan thánh dược, Chiến vương phát hiện chiếc bát ngọc đã bị khắc phù văn nguyền rủa có thể âm thầm làm bệnh nhân tổn thương. Việc dò biển ý thức người hầu không tìm ra chủ mưu nhưng khiến các Vương biết Thạch Hạo từng bị mưu sát trước đó. Bằng Cửu dùng Bằng trảo đánh gãy gậy gỗ và bắt bà lão Tần tộc, còn Minh vương đẩy lui vị Tôn giả ra tay can thiệp. Ba vị Tôn giả Thạch quốc đồng loạt rút pháp khí thần linh và tuyên bố sẵn sàng bình định Bất Lão sơn, khiến phía Tần tộc nhụt chí."},{"chuong":596,"tieuDe":"Vạn Giáo Đều Tới","tomTat":"Ba đại Tôn giả cùng các vương hầu Thạch quốc mang pháp khí cấp Thần ép Bất Lão sơn giải thích việc hãm hại Thạch Hạo, khiến Tần tộc phải đẩy một lão bộc ra nhận tội thay và người này lập tức bị Bằng Cửu giết chết. Tần Hạo mặc pháp y thần linh, cầm chiến kích bạc đứng ra bảo vệ đạo thống, nhưng Thạch Hạo tỉnh lại rồi kiên quyết từ chối lấy Tiên cốt của em trai và nói ra nguyện vọng cuối đời. Vì thân thể hắn không chịu nổi việc vượt hư không, mọi người giữ hắn lại, dùng nửa viên thánh dược và nhờ Tôn giả hỗ trợ luyện hóa để tạm trị thương. Sau đó, đệ tử Bổ Thiên các, bằng hữu từ Bách Đoạn sơn, các vương hầu, giáo chủ, Tôn giả và Hải tộc liên tiếp kéo tới thăm, khiến Bất Lão sơn trở thành nơi tụ hội của hàng ngàn đến hàng vạn truyền thừa. Khi một lão già Bất Lão sơn đề nghị truyền lại bảo thuật Côn Bằng, Thạch Hạo quyết khắc hai bộ cho Thạch quốc và Thạch thôn, nhưng mới hoàn thành khoảng một nửa chân nghĩa đã ho ra máu và gần hôn mê. Cuối cùng, Thạch Vân Phong dẫn hơn nửa người Thạch thôn tới đón, khẳng định sẽ dùng tổ khí cùng mọi vật liệu trong thôn để cứu chữa, khiến Thạch Hạo rơi lệ và đồng ý trở về quê nhà."},{"chuong":597,"tieuDe":"Hồ Niết Bàn","tomTat":"Người Thạch thôn đau xót trước thương thế của Thạch Hạo và muốn đưa cậu về nhà, nhưng Chiến vương khuyên tạm hoãn để tiếp tục tìm cách cứu chữa. Thạch Vân Phong lấy Bất Lão tuyền do Thạch Hạo từng mang về, giúp sắc mặt và sinh cơ của cậu tạm thời khá hơn. Theo đề nghị của Minh vương, mọi người dựng hồ Niết bàn bằng linh đan, dược thảo và thần dịch, còn Tần Di Ninh bố trí theo pháp môn Ngũ hành niết bàn. Dược lực chỉ cải thiện thương tích nhất thời, trong khi phù văn nguyền rủa vẫn ăn sâu khiến Chí Tôn cốt tiếp tục giải thể. Biết thời gian không còn nhiều, Thạch Hạo bất chấp sự ngăn cản để khắc Bảo thuật Côn Bằng lên một khối cốt, muốn lưu truyền cho Thạch quốc và Thạch thôn. Trương Trọng xác nhận vẻ hồi phục của cậu thực chất do Chí Tôn huyết bị tiêu hao để kéo dài tính mạng, đồng thời kết luận việc cấy Tiên cốt đã quá muộn. Hy vọng cuối cùng tan vỡ khiến Tần Di Ninh gần như ngất đi và Thạch Tử Lăng đau đớn phát cuồng. Chiến vương cùng người Thạch thôn cuối cùng đưa Thạch Hạo đã hôn mê rời Bất Lão sơn, mở thông đạo tại một tòa thành gần đó để trở về Thạch quốc."},{"chuong":598,"tieuDe":"Tuyệt Lộ Chém Cốt","tomTat":"Tin Thạch Hạo trọng thương trở về và chỉ còn hơn một ngày để sống khiến tám vực chấn động, vô số cường giả đổ về Thạch đô tiễn biệt vị thiếu niên chí tôn từng bảo vệ chúng sinh. Thạch Quốc và Thạch thôn dốc hết bảo vật cứu chữa, từ tổ khí, Long Huyết mộc, Hắc Kim trùng đến bồ đoàn Côn mộc, quả Ngân Đào và thần tửu, nhưng vẫn không đủ để luyện Cửu chuyển thần đan hay hóa giải lời nguyền. Ngay cả khi Ngũ Hành, Chu Tước và Chân Hoàng Niết bàn pháp được phối hợp, lần cứu chữa cuối cùng vẫn thất bại; cha mẹ Thạch Hạo vì thế định lấy mạng huyết tế tại Thần Lô cốc, song bị Chiến Vương kịp thời ngăn lại theo ý hắn. Biết tử kỳ đã gần, Thạch Hạo cố lưu lại một nửa pháp môn Côn Bằng cho Thạch tộc rồi gặp riêng Tần Hạo, giao phó em chăm sóc cha mẹ và chỉ rõ rằng con đường vô địch chân chính không thể dựa hoàn toàn vào Chí Tôn cốt. Trước sự chứng kiến của các cường giả hộ pháp, hắn bình tĩnh tự lấy khối Chí Tôn cốt đã vỡ chưa đầy hai phần ba khỏi ngực, yêu cầu thần y Trương Trọng ghép nó cho Tần Hạo. Cuối cùng, Thạch Hạo căn dặn em trai rằng nếu muốn vượt lên giới hạn của hai khối cốt, một ngày nào đó phải dám hủy bỏ chúng, dùng Chí Tôn huyết tẩm bổ toàn thân để bước sang con đường lột xác khác."},{"chuong":599,"tieuDe":"Tiểu Thạch Bước Cuối Con Đường","tomTat":"Tần Di Ninh và Thạch Tử Lăng đau đớn, tự trách khi Thạch Hạo hấp hối sau khi tự lấy Chí Tôn cốt, nhưng nó không oán cha mẹ và kiên quyết không hy sinh Tần Hạo để cứu mình. Trương Trọng xác nhận khối cốt không thể cứu Thạch Hạo nhưng có thể ghép cho Tần Hạo nhờ máu chí tôn cùng Tiên cốt hoàn chỉnh, và ca nối cốt sau đó thành công. Chứng kiến con trưởng sắp chết, Thạch Tử Lăng lập huyết thệ sẽ hủy diệt Tiên điện và san bằng nơi truyền thừa của bảy Thần. Chiến vương, Bằng vương và Minh vương dốc thần lực kéo dài sinh mệnh cho Thạch Hạo, trong khi người thân cùng bằng hữu lần lượt tới tiễn biệt. Sau khi biết Tần Hạo đã tiếp nhận cốt thành công, Thạch Hạo theo người Thạch thôn dùng tổ tế đàn trở về quê giữa tiếng tiễn đưa vang dội của toàn đô thành. Nó sống qua đêm đầu tiên tại Thạch thôn rồi cùng Thạch Phi Giao tới ngọn núi thấp cách thôn mười dặm, chọn nơi có thể nhìn về quê nhà làm chỗ an táng. Ngay sau đó sắc máu trên mặt Thạch Hạo biến mất, tinh khí thần suy kiệt và sinh mệnh đi đến phần cuối, khiến mọi người hoảng hốt nhào tới."},{"chuong":600,"tieuDe":"Chết Đi","tomTat":"Sau khi trở về Thạch thôn, Thạch Hạo nhanh chóng cạn kiệt sinh lực vì nguyền rủa tiếp tục phá hoại cơ thể, trong khi việc mất Chí Tôn cốt khiến nó không thể chống đỡ. Người thân, bạn bè và dân làng cùng truyền thần lực, cầu nguyện và tìm linh dược cứu nó, nhưng Ngân Đào đã mất phần lớn hiệu quả. Bóng Lông và Tiểu Hồng mang giọt thần tửu Côn Bằng cuối cùng tới, giúp Thạch Hạo tỉnh lại trong thời gian ngắn nhưng không thể hóa giải nguyền rủa. Nhị Mãnh cõng Thạch Hạo đi qua những con đường quen thuộc, để nó nhìn lại quê hương và nhớ về tuổi thơ. Thạch Hạo tiếc nuối vì không còn cơ hội lên thượng giới hay tìm Liễu Thần, rồi dặn Đại Bằng, Tiểu Thanh và Tử Vân tiếp tục bảo vệ Thạch thôn. Khi mặt trời lặn, nó mất thị lực, cố giơ tay từ biệt mọi người rồi tắt thở. Ngày hôm sau, dân làng đặt Thạch Hạo vào quan tài và mai táng trên ngọn núi thấp gần thôn theo di nguyện của nó."}];
